// @ts-nocheck
/* eslint-disable */
/**
 * Prospects page engine. GENERATED by tools/sync-prospects.mjs from web/pages/contracts.xhtml — do not edit; change the script and run `npm run prospects:sync`.
 *
 * The page script of the Java screen (contracts.xhtml), same behaviour line by line: the customer list loaded page by page with infinite scroll
 * (search, sort, filter on the server), the enrichment of the rows that the list does not carry, the detail side panel with its two tabs
 * (details, documents with upload / drag and drop / preview / download / delete), the "create lead" modal with its confirm and success popups.
 *
 * WHY it is imperative DOM code and not Angular components: the Java page is a data-driven DOM application whose HTML is drawn from API data as
 * strings. Porting it 1:1 is what guarantees the screen, texts and states are identical to the production system; the template (prospects.html)
 * and stylesheet (prospects.scss) are the Java markup / CSS verbatim and the engine binds to them through the same ids / data-* contract.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-prospects.mjs):
 *   - the environment is injected (ProspectsEnv): messages, fetch (every /board/… request of the page), SweetAlert, navigation to other pages
 *     (the Java addresses go through javaLinkToRoute in the host), the session (employee id, user, branch), sessionStorage, and the two
 *     p:remoteCommand of the document tab (env.docs) — in Java these were EL expressions, the URL and JSF;
 *   - the JSF tags of the document list are the elements JSF writes; the rows are drawn by ctDocRowsHtml (the body of the ui:repeat);
 *   - the DOMContentLoaded handlers wait for the end of the script, as they did when the document was parsed (see port-kit.mjs);
 *   - global listeners, timers, the IntersectionObserver, the modal that is moved to <body>, the blob URLs of a download and the window.* names
 *     are removed by the function returned from startProspects().
 */

import type { ProspectDoc } from './prospects.docs';

export interface ProspectsEnv {
  /** the button registry (core/permissions/access-buttons.ts): may the signed-in user use this button? — the "3 dots" of a row is PL-PR-LS-06, the download button and the trash icon of a document row are PL-PR-LS-11 / 12 */
  access: (code: string) => boolean;
  /** a role check (PermissionService.has): the items of the row menu are role checks (แก้ไข / ระงับ Edit · ดู View · Waitlist Change_Assign · ลบ Trash) */
  can: (role: string) => boolean;
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** every request of the page (`/board/prospect-list`, `/board/prospect-enrich`, `/board/lead-create`, `/board/prospect/attachments`, the master data, `/docproxy`) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** #{request.contextPath}: prefix of the BFF paths ('' — the Angular app has no context path) */
  ctx: string;
  /** SweetAlert v2 (js/sweetalert/sweetalertv1.min.js) */
  swal: (options: Record<string, unknown>) => Promise<unknown>;
  /** window.location.href = '<Java address>': the host turns the address into a route */
  navigate: (javaUrl: string) => void;
  /** #{commonBean.ssEmployeeId}, #{sessionScope.ssousername}, #{sessionScope.ss_branch_code} */
  session: { employeeId: string; username: string; branchCode: string };
  /** sessionStorage (the "lead already created" memory of the browser tab) */
  storage: { getItem(key: string): string | null; setItem(key: string, value: string): void };
  /** the remote commands rc_ctLoadDocs / rc_ctDeleteDoc: the documents of a prospect as ContractView.loadProspectDocs() lists them (newest first) */
  docs: { load(pid: unknown): Promise<ProspectDoc[]>; remove(pid: unknown, docNo: unknown): Promise<ProspectDoc[]> };
  /** js/lead/lead_create_dropdowns.js (window.LeadCreateDropdowns), made with the fetch to use */
  leadCreateDropdowns: (deps: { fetch: (input: string, init?: RequestInit) => Promise<Response> }) => { create(opts?: Record<string, unknown>): any };
}

export function startProspects(env: ProspectsEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });


  /* ═══════════ the JSF part of the page, replaced by the host (pages/contracts.xhtml: h:form ctDocForm, ui:repeat, p:remoteCommand) ═══════════ */
  /* the body of <ui:repeat value="#{contractView.prospectDocs}" var="doc"> of the original: one row per document, written the way JSF writes it
     (the values are escaped; no, attachfile, filename, kind come from the bean: ContractView.toDocRow) */
  function ctDocEsc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function ctDocRowsHtml(docs) {
    return docs.map(function (doc) {
      return "\n                                        <div class=\"ct-doc-row\" data-no=\""
        + ctDocEsc(doc.no)
        + "\" data-src=\""
        + ctDocEsc(doc.attachfile)
        + "\" data-name=\""
        + ctDocEsc(doc.filename)
        + "\" data-kind=\""
        + ctDocEsc(doc.kind)
        + "\">\n                                            <div class=\"ct-doc-name\">\n                                                <i class=\"fas fa-file-lines ct-doc-ic\" style=\"color:#35236A;\"></i>\n                                                <span>"
        + ctDocEsc(doc.filename)
        + "</span>\n                                            </div>\n                                            <div class=\"ct-doc-actions\">\n                                                "
        + (env.access("PL-PR-LS-11") ? "<button class=\"ct-dl-btn\" type=\"button\">\n                                                    <img class=\"ct-dl-ic\" src=\"assets/images/icon/fi_download.svg\" alt=\"\" style=\"width:14px;height:14px;object-fit:contain;\"/>\n                                                    <span>" + ctDocEsc(env.t("label.contracts.download_btn")) + "</span>\n                                                </button>" : '')
        + "\n                                                "
        + (env.access("PL-PR-LS-12") ? "<i class=\"fas fa-trash ct-doc-del\" title=\"" + ctDocEsc(env.t("label.contracts.delete_doc_tip")) + "\" style=\"cursor:pointer;color:#CD1515;\"></i>" : '')
        + "\n                                            </div>\n                                        </div>\n                                    ";
    }).join('');
  }
  /* the list as the server renders it when there is no document (ui:fragment rendered="#{empty contractView.prospectDocs}") */
  var CT_DOC_EMPTY_HTML = "\n                                        <div class=\"ct-doc-empty\" style=\"color:#9CA3AF;padding:8px 4px;\">" + ctDocEsc(env.t("label.contracts.empty_attachments")) + "</div>\n                                    ";

  /* the roles of the items of the 3-dots menu of a row (แก้ไข / ดู / Waitlist / ระงับ / ลบ): the icon is drawn when the user holds any of them */
  var ROW_MENU_ROLES = ['Pipeline_Prospect_Edit', 'Pipeline_Prospect_View', 'Pipeline_Prospect_Change_Assign', 'Pipeline_Prospect_Trash'];
  var downloadUrls = [];   /* blob URLs of the downloads that are not revoked yet (destroy() revokes them) */
  var rc_ctLoadDocs, rc_ctDeleteDoc;
  /* PrimeFaces sends [{ name, value }]; the bean read them with getRequestParameterMap() */
  function ctRcParams(params) {
    var o = {};
    (params || []).forEach(function (p) { o[p.name] = p.value; });
    return o;
  }
  /* update="ctDocList" + oncomplete="window.ctAfterDocsLoaded()": the list is drawn again from the answer, then the page binds its rows */
  function ctRcUpdate(answer) {
    return answer.then(function (docs) {
      if (destroyed) { return; }
      var list = document.getElementById('ctDocForm:ctDocList');
      if (list) { list.innerHTML = docs.length ? ctDocRowsHtml(docs) : CT_DOC_EMPTY_HTML; }
      if (window.ctAfterDocsLoaded) { window.ctAfterDocsLoaded(); }
    });
  }
  /* p:remoteCommand name="rc_ctLoadDocs" actionListener="#{contractView.panelLoadProspectDocs()}" */
  rc_ctLoadDocs = window.rc_ctLoadDocs = function (params) {
    return ctRcUpdate(env.docs.load(ctRcParams(params).pid));
  };
  /* p:remoteCommand name="rc_ctDeleteDoc" actionListener="#{contractView.panelDeleteProspectDocument()}" */
  rc_ctDeleteDoc = window.rc_ctDeleteDoc = function (params) {
    var p = ctRcParams(params);
    return ctRcUpdate(env.docs.remove(p.pid, p.docNo));
  };
  /* the context-menu items of a row went to a Java address with window.location.href: the host maps it to the route */
  window.ctNavigate = function (url) { env.navigate(url); };

(function () {
                /* ข้อมูลตาราง fetch จาก /board/prospect-list ทีละหน้า (ProspectListServlet) แล้ว render
                   เป็น <tr> ฝั่ง JS — ค้นหา/จัดเรียง/กรอง ส่งไปทำที่ backend, JS ดูแลการต่อหน้า + พาเนล */

                function g(id) { return document.getElementById(id); }

                /* SOURCE_BADGE_COLOR_START */
                /*
                 * จัดสี badge คอลัมน์ "ที่มา"
                 * - มี palette 20 สี
                 * - ที่มาเดียวกัน (ตัดช่องว่าง/ไม่สนตัวพิมพ์เล็กใหญ่) ใช้สีเดิมเสมอในหน้าปัจจุบัน
                 * - คำนวณสีจากข้อความแบบ deterministic จึงคงสีเดิมแม้ refresh/เปลี่ยนเครื่อง
                 * - ตัวอักษรใช้สีหลัก และพื้นหลังใช้สีเดียวกัน opacity 20% ตาม Figma
                 */
                var ctSourceBadgeColors = (function () {
                    var PALETTE = [
                        '#0C8E6A', '#14A2D0', '#0D61CF', '#462D90', '#C92A76',
                        '#CD1515', '#DA6624', '#DA9A24', '#87B236', '#626262',
                        '#2D715E', '#338BA7', '#295794', '#5A2C94', '#8A124C',
                        '#7B0505', '#A15D37', '#A28537', '#5F7A15', '#3C3C3C'
                    ];
                    var sourceMap = Object.create(null);

                    function normalizeSource(source) {
                        return String(source || '')
                            .replace(/^\s+|\s+$/g, '')
                            .replace(/\s+/g, ' ')
                            .toLowerCase();
                    }

                    function colorIndex(source) {
                        var hash = 2166136261;
                        for (var i = 0; i < source.length; i++) {
                            hash ^= source.charCodeAt(i);
                            hash = Math.imul(hash, 16777619);
                        }
                        return (hash >>> 0) % PALETTE.length;
                    }

                    function rgba(hex, opacity) {
                        var value = String(hex || '').replace('#', '');
                        var r = parseInt(value.substring(0, 2), 16);
                        var g = parseInt(value.substring(2, 4), 16);
                        var b = parseInt(value.substring(4, 6), 16);
                        return 'rgba(' + r + ', ' + g + ', ' + b + ', ' + opacity + ')';
                    }

                    function getStyle(source) {
                        var key = normalizeSource(source);
                        if (!key) {
                            return { background: '#E5E7EB', color: '#4B5563' };
                        }
                        if (sourceMap[key]) return sourceMap[key];

                        var color = PALETTE[colorIndex(key)];
                        sourceMap[key] = {
                            background: rgba(color, 0.2),
                            color: color
                        };
                        return sourceMap[key];
                    }

                    function applyAll(root) {
                        var scope = root || document;
                        var badges = scope.querySelectorAll('.ct-source-badge[data-source]');
                        Array.prototype.forEach.call(badges, function (badge) {
                            var source = badge.getAttribute('data-source') || '';
                            var style = getStyle(source);
                            badge.style.backgroundColor = style.background;
                            badge.style.color = style.color;
                        });
                    }

                    return {
                        palette: PALETTE.slice(),
                        getStyle: getStyle,
                        applyAll: applyAll
                    };
                })();
                window.ctSourceBadgeColors = ctSourceBadgeColors;
                /* SOURCE_BADGE_COLOR_END */

                /* ===== เอกสารประกอบ — ข้อมูลจริงจาก server (#{contractView.prospectDocs}) ผ่าน remoteCommand =====
                   พาเนล list ส่ง prospect id (pid) ให้ backend โหลด/อัปโหลด/ลบ แล้ว update รายการที่ server render
                   ★ โหลดแบบ lazy: ดึงเอกสารเฉพาะตอนเปิดแท็บ "เอกสารประกอบ" (ไม่ยิง ajax ทุกครั้งที่คลิกแถว)
                     + cache ตาม pid → สลับแท็บ/เปิดลูกค้าเดิมซ้ำ = ไม่โหลดใหม่ ทำให้ลื่นขึ้น */
                window.CT_CUR_PID = 0;
                window.CT_DOCS_LOADED_PID = null; /* pid ที่เอกสารถูก render อยู่ตอนนี้ (กันโหลดซ้ำ) */

                function ctDocsContainer() { return document.querySelector('#ctTabDocs .ct-doc-list'); }

                /* preview + ไฮไลต์ของแถวเอกสารที่เลือก (อ่าน data-* จากแถวที่ server render) */
                function ctSelectDocRow(row) {
                    if (!row) return;
                    document.querySelectorAll('#ctTabDocs .ct-doc-row').forEach(function (r) { r.classList.remove('active'); });
                    row.classList.add('active');
                    window.ctRenderPreview(row.getAttribute('data-kind') || 'file',
                                           row.getAttribute('data-src') || '',
                                           row.getAttribute('data-name') || '');
                }

                /* หลัง remoteCommand อัปเดตรายการเสร็จ: ผูก event (คลิก/ดาวน์โหลด/ลบ) + preview ไฟล์แรก */
                /* ไอคอนตามชนิดไฟล์ (ดูจากนามสกุล): word/excel/pdf/zip ฯลฯ = สัญลักษณ์ของมัน, อื่น ๆ = รูปเอกสารทั่วไป
                   ใช้ชุดสี/ไอคอนเดียวกับตัวอย่างไฟล์ (ctRenderPreview) ให้สอดคล้องกัน */
                function ctDocIconFor(name) {
                    var ext = String(name || '').split('.').pop().toLowerCase();
                    var map = {
                        pdf:  ['fa-file-pdf', '#CD1515'],
                        doc:  ['fa-file-word', '#2B579A'], docx: ['fa-file-word', '#2B579A'],
                        xls:  ['fa-file-excel', '#217346'], xlsx: ['fa-file-excel', '#217346'], csv: ['fa-file-excel', '#217346'],
                        ppt:  ['fa-file-powerpoint', '#C43E1C'], pptx: ['fa-file-powerpoint', '#C43E1C'],
                        zip:  ['fa-file-zipper', '#B45309'], rar: ['fa-file-zipper', '#B45309'], '7z': ['fa-file-zipper', '#B45309'],
                        png:  ['fa-file-image', '#0D9488'], jpg: ['fa-file-image', '#0D9488'], jpeg: ['fa-file-image', '#0D9488'],
                        gif:  ['fa-file-image', '#0D9488'], webp: ['fa-file-image', '#0D9488'], bmp: ['fa-file-image', '#0D9488'], svg: ['fa-file-image', '#0D9488']
                    };
                    return map[ext] || ['fa-file-lines', '#35236A'];   /* ไฟล์ทั่วไป = รูปเอกสาร */
                }
                window.ctAfterDocsLoaded = function () {
                    var rows = document.querySelectorAll('#ctTabDocs .ct-doc-row');
                    rows.forEach(function (row) {
                        var ic = row.querySelector('.ct-doc-ic');
                        if (ic) {
                            var info = ctDocIconFor(row.getAttribute('data-name'));
                            ic.className = 'fas ' + info[0] + ' ct-doc-ic';
                            ic.style.color = info[1];
                        }
                        row.addEventListener('click', function () { ctSelectDocRow(row); });
                        var dl = row.querySelector('.ct-dl-btn');
                        if (dl) dl.addEventListener('click', function (e) {
                            e.stopPropagation();
                            window.ctDownloadDoc(row.getAttribute('data-src'), row.getAttribute('data-name'));
                        });
                        var del = row.querySelector('.ct-doc-del');
                        if (del) del.addEventListener('click', function (e) {
                            e.stopPropagation();
                            window.ctDeleteDoc(row.getAttribute('data-no'));
                        });
                    });
                    if (rows.length) { ctSelectDocRow(rows[0]); }
                    else { window.ctRenderPreview('empty'); }
                    window.CT_DOCS_LOADED_PID = window.CT_CUR_PID; /* mark cached สำหรับลูกค้าคนนี้ */
                };

                /* เปิดพาเนล/สลับลูกค้า: จำ pid ไว้เฉย ๆ — ยังไม่ยิง ajax (lazy โหลดตอนเปิดแท็บเอกสาร) */
                function ctSetPanelProspect(pid) {
                    window.CT_CUR_PID = pid || 0;
                }

                /* เปิดแท็บเอกสาร: โหลดเฉพาะเมื่อยังไม่ได้ cache ไว้สำหรับลูกค้าคนนี้ (สลับไปมา = instant) */
                function ctEnsureDocsLoaded() {
                    if (window.CT_DOCS_LOADED_PID === window.CT_CUR_PID) { return; }
                    var c = ctDocsContainer();
                    if (c) { c.innerHTML = '<div class="ct-doc-empty" style="color:#9CA3AF;padding:8px 4px;">' + env.t("label.contracts.loading_docs") + '</div>'; }
                    window.ctRenderPreview('empty');
                    if (window.rc_ctLoadDocs) { rc_ctLoadDocs([{ name: 'pid', value: window.CT_CUR_PID }]); }
                }

                /* ลบเอกสาร 1 รายการ (persist) */
                /* ★ 21/08: เปลี่ยนจาก window.confirm() เบราว์เซอร์ล้วน เป็น swal แบบ confirm (สไตล์เดียวกับ
                   contracts_master_data.xhtml ที่แก้คู่กันตอนนี้ ให้ popup ไปในแนวเดียวกันทั้งระบบ) */
                window.ctDeleteDoc = function (no) {
                    if (!no) return;
                    env.swal({
                        title: env.t("label.contracts.confirm_delete_doc"),
                        icon: 'warning',
                        buttons: [env.t("chat.cancel"), env.t("label.cmd.delete_tip")],
                        dangerMode: true
                    }).then(function (willDelete) {
                        if (willDelete && window.rc_ctDeleteDoc) {
                            rc_ctDeleteDoc([{ name: 'pid', value: window.CT_CUR_PID }, { name: 'docNo', value: no }]);
                        }
                    });
                };

                window.ctDeleteProspect = function (id) {
                    if (!id) return;
                    env.swal({
                        title: env.t("app.prospects.confirmDelete"),
                        icon: 'warning',
                        buttons: [env.t("chat.cancel"), env.t("label.cmd.delete_tip")],
                        dangerMode: true
                    }).then(function (willDelete) {
                        if (willDelete) { /* the delete of a prospect has no call yet */ }
                    });
                };

                window.ctRestoreProspect = function (id) {
                    if (!id) return;
                    var rowEl = document.querySelector('#ctTableBody tr[data-id="' + id + '"]');
                    document.querySelectorAll('.ct-ctx-menu.show').forEach(function (m) { m.classList.remove('show'); });
                    env.swal({
                        title: env.t("app.prospects.confirmRestore"),
                        icon: 'warning',
                        buttons: [env.t("chat.cancel"), env.t("app.prospects.restore")]
                    }).then(function (ok) {
                        if (!ok) { return; }
                        env.fetch(env.ctx + '/board/prospect-trash-action', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            credentials: 'same-origin',
                            body: JSON.stringify({ prospectId: id, action: 'RESTORE' })
                        }).then(function (res) {
                            return res.text().then(function (t) {
                                if (res.ok) {
                                    if (rowEl && rowEl.parentNode) { rowEl.parentNode.removeChild(rowEl); }
                                    env.swal({ title: env.t("app.prospects.restored"), icon: 'success', timer: 1500, buttons: false });
                                    return;
                                }
                                var j = null;
                                try { j = JSON.parse(t); } catch (e) { j = null; }
                                var why = j && j.error ? (j.error.description || j.error.message || '') : '';
                                env.swal({ title: env.t("app.prospects.restoreFailed"), text: why || ('HTTP ' + res.status), icon: 'warning' });
                            });
                        }).catch(function () { env.swal({ title: env.t("app.prospects.restoreFailed"), text: 'เชื่อมต่อเซิร์ฟเวอร์ไม่ได้', icon: 'warning' }); });
                    });
                };

                /* the item of the 3-dots menu that changes the state of a live record (POST /prospects/{id}/status-changes):
                   draft -> Release, active -> Suspend (block), suspended -> Unblock (release again). Release / unblock say who is responsible. */
                function ctStatusItem(r) {
                    if (!env.can('Pipeline_Prospect_Edit')) { return ''; }
                    var kind = ctStatusKind(String(r.status || '').trim() || env.t('app.prospects.statusActive'));
                    var cfg = kind === 'draft' ? { target: 'RELEASE', icon: 'fa-circle-check', key: 'app.prospects.release' }
                            : kind === 'suspended' ? { target: 'RELEASE', icon: 'fa-lock-open', key: 'app.prospects.unblock' }
                            : kind === 'active' ? { target: 'BLOCK', icon: 'fa-ban', key: 'app.prospects.suspend' } : null;
                    if (!cfg) { return ''; }
                    return '<div class="ct-ctx-item" id="ctCtxStatus-' + r.id + '" onclick="ctChangeStatus(\'' + r.id + '\',\'' + cfg.target + '\',\'' + cfg.key + '\')"><i class="fas ' + cfg.icon + '"></i>' + ctEsc(env.t(cfg.key)) + '</div>';
                }
                function ctNewKey() {
                    if (window.crypto && window.crypto.randomUUID) { return window.crypto.randomUUID(); }
                    return String(Date.now()) + '-' + Math.random().toString(16).slice(2);
                }
                /* one Idempotency-Key per action (made here, sent in the body: the backend of the page puts it in the header) */
                function ctPostStatusChange(prospectId, target, assignment) {
                    var body = { prospectId: prospectId, targetStatus: target, idempotencyKey: ctNewKey() };
                    if (assignment) { body.assignment = assignment; }
                    return env.fetch(env.ctx + '/board/prospect-status-change', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'same-origin',
                        body: JSON.stringify(body)
                    }).then(function (res) {
                        return res.text().then(function (t) {
                            if (res.ok) { return { ok: true }; }
                            var j = null;
                            try { j = JSON.parse(t); } catch (e) { j = null; }
                            var why = j && j.error ? (j.error.description || j.error.message || '') : '';
                            var msg = ({ 403: 'ไม่มีสิทธิ์เปลี่ยนสถานะ', 409: 'ข้อมูลถูกเปลี่ยนไปแล้ว กรุณารีเฟรชแล้วลองใหม่', 422: 'ทำรายการไม่ได้' })[res.status] || ('เกิดข้อผิดพลาด (' + res.status + ')');
                            return { ok: false, message: msg + (why ? '\n' + why : '') };
                        });
                    }).catch(function () { return { ok: false, message: 'เชื่อมต่อเซิร์ฟเวอร์ไม่ได้' }; });
                }
                window.ctChangeStatus = function (id, target, labelKey) {
                    if (!id) return;
                    document.querySelectorAll('.ct-ctx-menu.show').forEach(function (m) { m.classList.remove('show'); });
                    var rowEl = document.querySelector('#ctTableBody tr[data-id="' + id + '"]');
                    var send = function (assignment) {
                        ctPostStatusChange(id, target, assignment).then(function (res) {
                            if (!res.ok) { env.swal({ title: env.t("app.prospects.statusChangeFailed"), text: res.message, icon: 'warning' }); return; }
                            env.swal({ title: env.t("app.prospects.statusChanged"), icon: 'success', timer: 1500, buttons: false });
                            ctReload();
                        });
                    };
                    if (target === 'BLOCK') {
                        env.swal({ title: env.t("app.prospects.confirmSuspend"), icon: 'warning', buttons: [env.t("chat.cancel"), env.t("app.prospects.suspend")] }).then(function (ok) { if (ok) { send(null); } });
                        return;
                    }
                    /* release / unblock: who is responsible (the people of /prospects/options?sets=responsibles) */
                    ctFetchJson(CT_API_OWNERS).then(function (data) {
                        /* { responsibles, waitlists }: the queues first, then the people (value wl:<id>) */
                        var people = ((data && data.waitlists) || []).map(function (w) { return { id: 'wl:' + w.id, name: w.name || w.id }; }).concat((data && data.responsibles) || []);
                        if (!people.length) { env.swal({ title: env.t("app.prospects.statusChangeFailed"), text: 'ไม่พบผู้รับผิดชอบที่เลือกได้', icon: 'warning' }); return; }
                        var select = document.createElement('select');
                        select.className = 'ct-filter-select';
                        select.setAttribute('data-ods-skip', '1');
                        select.innerHTML = people.map(function (o) { return '<option value="' + ctEsc(o.id) + '">' + ctEsc(o.name || o.code || o.id) + '</option>'; }).join('');
                        var current = rowEl ? String(rowEl.getAttribute('data-ownerid') || '') : '';
                        if (current && Array.prototype.some.call(select.options, function (op) { return op.value === current; })) { select.value = current; }
                        env.swal({ title: env.t("app.prospects.chooseResponsible"), content: select, buttons: [env.t("chat.cancel"), env.t(labelKey || "app.prospects.release")] }).then(function (ok) {
                            /* a person: destination EMPLOYEE; a queue (wl:<id>): destination WAITLIST (the body of this one is a GUESS: waitlistId, as responsibleEmployeeId is for a person) */
                            if (ok) { send(String(select.value).indexOf('wl:') === 0 ? { destination: 'WAITLIST', waitlistId: String(select.value).slice(3) } : { destination: 'EMPLOYEE', responsibleEmployeeId: select.value }); }
                        });
                    });
                };

                function openPanel(rowEl) {
                    if (!rowEl) return;
                    // highlight row
                    document.querySelectorAll('.ct-table tbody tr').forEach(function(r){ r.classList.remove('ct-row-active'); });
                    rowEl.classList.add('ct-row-active');

                    /* ★ 19/08: แถวนี้ยังไม่ได้เติมข้อมูลของ panel (ชุดที่ list ไม่ส่งมา) → ยิงเติมเฉพาะแถวนี้
                       ปกติชุดของทั้งหน้ากำลังมาอยู่แล้วตั้งแต่ตอน render — เส้นนี้เป็นตัวสำรอง
                       กรณีชุดนั้นล้มเหลว/ผู้ใช้กดเร็วกว่า (ctEnrichRows จะเรียก openPanel ซ้ำให้เองเมื่อได้ข้อมูล
                       และตั้ง data-enriched ไว้แล้ว จึงไม่วนซ้ำ) */
                    if (!rowEl.getAttribute('data-enriched')) {
                        ctEnrichRows([rowEl.getAttribute('data-id')]);
                    }

                    /* ข้อมูลมาจาก data-* ของแถว (ProspectListService เติมให้ครบตอนดึงแต่ละหน้าแล้ว
                       รวมเพศ/อีเมล/โซเชียล/ประเภทลูกค้า ที่ endpoint list ไม่ได้ส่งมาเอง) */
                    var d = rowEl.dataset || {};
                    var dash = function (v) { return (v != null && String(v).trim() !== '') ? v : '-'; };

                    /* ไม่มีรูป → รูป default (avatar ฟ้า) แทนการซ่อน + กันรูปจริงโหลดพัง (21/07) */
                    var DEFAULT_AVATAR = 'assets/images/icon/default_avatar.svg';
                    var photo = (d.avatar && d.avatar.trim()) ? d.avatar : DEFAULT_AVATAR;
                    var phEl = g('ctDetailPhoto');
                    phEl.onerror = function () { this.onerror = null; this.src = DEFAULT_AVATAR; };
                    phEl.src = photo;
                    phEl.style.display = 'block';
                    g('ctDName').textContent        = dash(d.name);
                    g('ctDCode').textContent        = dash(d.code);
                    var stCell = rowEl.querySelector('.ct-status');
                    var stTxt = stCell ? stCell.textContent.trim() : '';
                    g('ctDStatus').innerHTML = (stTxt && stTxt !== '-') ? ctStatusHtml(stTxt) : '';
                    g('ctOpenFull').onclick = function () { env.navigate(CT_VIEW_URL + encodeURIComponent(d.id) + (STATUS_STATE === 'deleted' ? '&trash=1' : '')); };
                    g('ctDPhone').innerHTML         = ctPhoneHtml(d);   /* ★ 15/09 รหัสโทร + รูปแบบ เหมือนคอลัมน์ในตาราง (data-phonecc/data-countrycode) */
                    g('ctDGender').textContent      = dash(d.gender);
                    g('ctDAvailTime').textContent   = dash(d.availtime);
                    g('ctDAvailChannel').textContent= dash(d.availchannel);
                    g('ctDAddr').textContent        = dash(ctPanelAddress(d));
                    g('ctDEmail').textContent       = dash(d.email);
                    g('ctDType').textContent        = dash(d.type);
                                        
                    ctFillOwnerSelect(d.owner, d.ownerid);
                    /* โซเชียล: ไอคอน + ชื่อ + ปุ่มคัดลอก (ค่าที่ไม่มีไม่แสดง) */
                    var socHtml = [['line', 'fab fa-line', 'ct-soc-line'], ['fb', 'fab fa-facebook', 'ct-soc-fb'], ['x', '', 'ct-soc-x'], ['ig', 'fab fa-instagram', 'ct-soc-ig']].map(function (sc) {
                        var v = String(d[sc[0]] == null ? '' : d[sc[0]]).trim();
                        if (/^[-–—]+$/.test(v)) { v = ''; }
                        return v ? '<div class="ct-soc-row"><span class="ct-soc-ic ' + sc[2] + '">' + (sc[1] ? '<i class="' + sc[1] + '"></i>' : CT_X_LOGO) + '</span><span class="ct-soc-txt">' + ctEsc(v) + '</span><button type="button" class="ct-soc-copy" data-copy="' + ctEsc(v) + '"><i class="fas fa-link"></i></button></div>' : '';
                    }).join('');
                    var socEl = g('ctDSocial');
                    socEl.innerHTML = socHtml || '-';
                    socEl.onclick = function (e) {
                        var b = e.target.closest ? e.target.closest('.ct-soc-copy') : null;
                        if (b && navigator.clipboard) { navigator.clipboard.writeText(b.getAttribute('data-copy')); }
                    };
                    /* ที่มา: ป้ายสีเดียวกับในตาราง */
                    var srcTxt = String(d.source == null ? '' : d.source).trim();
                    g('ctDSource').innerHTML = srcTxt ? '<span class="ct-badge ct-source-badge" data-source="' + ctEsc(srcTxt) + '"><span class="ct-badge-text">' + ctEsc(srcTxt) + '</span></span>' : '-';
                    ctSourceBadgeColors.applyAll(g('ctDSource'));
                    g('ctDRecorderCard').textContent = dash(d.recorder);
                    g('ctDOwnerView').textContent = dash(d.owner);
                    g('ctDRecorderView').textContent = dash(d.recorder);
                    ctOwnerMode(false);
                    /* โอกาสขายที่เปิดอยู่: ค่ามากับแถวเป็น r.oppcount (list ยังไม่ส่ง = 0) */
                    var oppN = String(d.oppcount == null ? '' : d.oppcount).trim();
                    g('ctDOppCount').textContent = (oppN !== '' ? oppN : '0') + ' ' + env.t('app.prospects.unitSheet');
                    /* ผู้ดูแล: ปุ่ม "เปลี่ยนผู้รับผิดชอบ" → โหมดแก้ (select + ปุ่ม "บันทึก"); ยังไม่มี API บันทึก = อัปเดตเฉพาะที่หน้านี้ */
                    g('ctChangeOwnerBtn').onclick = function () {
                        if (!g('ctOwnerCard').classList.contains('editing')) { ctOwnerMode(true); return; }
                        var sel = g('ctDOwnerSelect');
                        var picked = sel.value;
                        var pickedName = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].textContent.trim() : '';
                        var current = String(d.ownerid || '');
                        if (!picked || picked === current) { ctOwnerMode(false); return; }
                        var btn = g('ctChangeOwnerBtn');
                        btn.disabled = true;
                        ctAssignOwner(d.id, picked, current).then(function (res) {
                            btn.disabled = false;
                            if (!res.ok) { env.swal({ title: 'เปลี่ยนผู้รับผิดชอบไม่สำเร็จ', text: res.message, icon: 'warning' }); return; }
                            if (picked.indexOf('wl:') === 0) { ctOwnerMode(false); ctReload(); return; }
                            rowEl.setAttribute('data-owner', pickedName);
                            rowEl.setAttribute('data-ownerid', picked);
                            var oc = rowEl.querySelector('.ct-sp');
                            if (oc) { oc.innerHTML = ctOwnerCell(pickedName); }
                            g('ctDOwnerView').textContent = dash(pickedName);
                            ctOwnerMode(false);
                        });
                    };

                    // เอกสารประกอบ: จำลูกค้าที่เลือกไว้ก่อน แล้วค่อย lazy-load ตอนเปิดแท็บเอกสาร (ไม่หน่วงตอนคลิกแถว)
                    ctSetPanelProspect(d.id);

                    // open panel
                    g('ctRightPanel').classList.add('open');
                    // switch to detail tab
                    switchTab('detail');
                    // ให้ card รายละเอียดสูงเท่า card ตารางซ้าย
                    syncPanelHeight();
                    tmo(syncPanelHeight, 60);
                    tmo(syncPanelHeight, 320);
                }
                window.ctOpenPanel = openPanel;

                /* ★ 18/08: ตัดดับเบิลคลิกแถว -> เปิดหน้ารายละเอียดเต็มออกตามที่ user สั่ง
                   (คลิกแถวครั้งเดียวเปิด panel ขวาซึ่งมีข้อมูลครบอยู่แล้ว — ดับเบิลคลิกที่เผลอโดนพาไปอีกหน้าโดยไม่ตั้งใจ
                   ★ 10/09: ไอคอนตา (ct-eye) เดิมเปลี่ยนเป็นเมนู 3 จุด "แก้ไข/ดู" (ctCtxToggle) แล้ว ไม่กระทบส่วนนี้) */

                /* ความสูง panel ขวา: จัดการด้วย CSS flex แล้ว (.ct-panel ยืดเต็มความสูง .ct-body อัตโนมัติ
                   ตาม .ct-main-card ฝั่งซ้าย) — ไม่ต้องคำนวณ/ตั้ง px เอง จึง responsive ตามจอจริง ๆ */
                function syncPanelHeight() { /* no-op: ปล่อยให้ CSS flex ยืดหดเอง */ }

                function closePanel() {
                    g('ctRightPanel').classList.remove('open');
                    document.querySelectorAll('.ct-table tbody tr').forEach(function(r){ r.classList.remove('ct-row-active'); });
                }

                function switchTab(tabName) {
                    document.querySelectorAll('.ct-tab').forEach(function(t){ t.classList.toggle('active', t.getAttribute('data-tab') === tabName); });
                    document.querySelectorAll('.ct-tab-content').forEach(function(c){ c.classList.toggle('active', c.id === 'ctTab' + (tabName === 'detail' ? 'Detail' : tabName === 'opportunity' ? 'Opportunity' : 'Docs')); });
                    if (tabName === 'docs') { ctEnsureDocsLoaded(); } /* lazy: โหลดเอกสารตอนเปิดแท็บนี้เท่านั้น */
                }

                function initPanel() {
                    g('ctPanelClose').addEventListener('click', closePanel);
                    document.querySelectorAll('.ct-tab').forEach(function(tab){
                        tab.addEventListener('click', function(){ switchTab(tab.getAttribute('data-tab')); });
                    });
                }

                /* ===== ตารางลูกค้า: โหลดทีละหน้าจาก /board/prospect-list + infinite scroll =====
                   เดิม server render ทุกแถวทีเดียว (ดึง prospect ทุกหน้ามาก่อน) — พอเปิดใช้ข้อมูล
                   ย้อนหลังหลายปีจะโหลดไม่ไหว. ตอนนี้: หน้าแรก CT_PER_PAGE แถว แล้วเลื่อนลงใกล้
                   ท้ายตารางค่อยขอหน้าถัดไปต่อท้าย จนกว่าจะครบ
                   ★ ค้นหา/กรอง/เรียง ส่งเป็น query param ไปคำนวณที่ backend ทั้งหมด
                     จึงค้นเจอ "ทุกแถวย้อนหลัง" ไม่ใช่เฉพาะแถวที่โหลดมาแล้ว */
                var CT_API_LIST   = env.ctx + '/board/prospect-list';
                /* ★ 19/08: ข้อมูลส่วนที่ /prospects (list) ไม่ส่งมา — ขอตามหลังทีเดียวทั้งหน้า (ดู ProspectEnrichServlet) */
                var CT_API_ENRICH = env.ctx + '/board/prospect-enrich';
                var CT_API_MASTER = env.ctx + '/board/chat-master-data?type=marketing-channels';
                var CT_API_PROV   = env.ctx + '/board/prospect-options?set=provinces';
                var CT_API_COUNTRY = env.ctx + '/board/prospect-options?set=countries';
                var CT_API_DIST   = env.ctx + '/board/prospect-options?set=districts&provinceId=';
                /* ★ 28/09: ตัวกรอง "พนักงานขาย" กลับมายิง /board/sale-persons (master-data/sale-persons) —
                   ทดสอบ UAT จริงแล้ว GET /prospects?salePersonId= กรองด้วย salePerson.id
                   (salePerson.id ของ GGW-001 → 22 แถว salePersonCode GGW-001 ทั้งหมด, GGW-002 → 3 แถว)
                   ส่วน employee.id ที่ใช้อยู่เดิม (★ 28/08 ยิง /board/employees) ได้ 0 แถวเสมอ
                   — backend ยังไม่มี param กรองตาม employee (ผู้บันทึก) employeeId/employeeIds ถูกเมิน */
                var CT_API_AGENTS = env.ctx + '/board/employees';
                var CT_API_AGENT_FILTER = env.ctx + '/board/prospect-options?set=responsibleFilter';
                var CT_PHONE_ICON = 'assets/images/icon/fi_phone.svg';
                var CT_AVATAR_DEF = 'assets/images/icon/default_avatar.svg';
                var CT_VIEW_URL   = 'contracts_master_data.face?pid=1&page_id=1&act=2&action_type=view&pms=detail&id=';
                /* ★ แก้ไข — action_type=edit เหมือนปุ่ม "แก้ไขข้อมูล" ของหน้า contracts_master_data.xhtml เอง */
                var CT_EDIT_URL   = 'contracts_master_data.face?pid=1&page_id=1&act=2&action_type=edit&pms=detail&id=';
                var CT_MSG_EMPTY  = env.t("label.contracts.empty_customer");
                var CT_MSG_ALL    = env.t("label.contracts.filter_all");
                var CT_MSG_ERROR  = env.t("label.dashboard.backend_error");
                var CT_MSG_VIEW   = env.t("label.contracts.view_detail_tip");
                var CT_MSG_EDIT   = env.t("label.ld2.edit");
                /* ★ 13/08: ข้อความแยกตามชนิดความผิดพลาด — เดิมทุกเคส (token หมดอายุ / servlet
                   ไม่มีเพราะ deploy ไม่ครบ / backend 500 / เน็ตไม่ถึง) ขึ้นว่า "เชื่อมต่อ backend
                   ไม่ได้" เหมือนกันหมด ทำให้ไล่หาสาเหตุผิดทาง */
                var CT_MSG_ERR_AUTH   = env.t("label.contracts.error_auth");
                var CT_MSG_ERR_MISSING = env.t("label.contracts.error_endpoint");
                var CT_MSG_ERR_SERVER = env.t("label.contracts.error_server");

                var CT_PER_PAGE   = 20;   /* จำนวนแถวต่อ 1 ครั้งที่โหลด (ตรงกับ ProspectListService.DEFAULT_PER_PAGE) */
                var CT_COLSPAN    = 9;    /* จำนวนคอลัมน์ของตาราง — ใช้กับแถวสถานะ (ว่าง/ผิดพลาด/skeleton) — 8 เดิม + ทีมขาย/พนักงานขาย */
                var CT_NEAR_END_PX = 300; /* เหลือระยะเท่านี้ถึงท้ายตาราง = เริ่มโหลดหน้าถัดไป */

                var SORT_STATE = 'date_desc';
                var SEARCH_Q = '';
                var STATUS_STATE = '';
                /* เก็บเป็น id เพราะ backend กรองด้วย id (ไม่ใช่ชื่อ) */
                var FILTER = { sourceIds: [], countryId: '', provinceId: '', districtId: '', salePersonId: '' };
                /* ★ 20/08: ตัวกรอง (ที่มา/จังหวัด/พนักงานขาย) โหลดครั้งแรกจริงตอนกดเปิดตัวกรองเท่านั้น
                   เดิม ctBuildFilterOptions() ยิง 3 เส้น (marketing-channels/provinces/sale-persons)
                   ตั้งแต่ DOMContentLoaded ทุกครั้งที่เปิดหน้า ไม่ว่าจะกดปุ่มตัวกรองหรือไม่ (บั๊กแบบเดียวกับ
                   ที่เจอในแดชบอร์ด — ดู bindAssignOnce ของ dashboard.js) */
                var CT_FILTER_OPTS_LOADED = false;

                /* สถานะการไล่โหลดหน้า */
                var CT_PAGE = 0;          /* หน้าที่โหลดมาแล้วล่าสุด (0 = ยังไม่โหลด) */
                var CT_TOTAL_PAGES = -1;  /* -1 = backend ไม่ส่ง meta มา ให้เดาจากจำนวนแถวที่ได้ */
                var CT_LOADING = false;
                var CT_DONE = false;      /* true = ไม่มีหน้าถัดไปแล้ว */
                var CT_SEEN = {};         /* กันแถวซ้ำ เผื่อ backend เรียงไม่คงที่ระหว่างหน้า */
                var CT_OBS = null;

                function ctRows(){ return Array.prototype.slice.call(document.querySelectorAll('#ctTableBody tr[data-id]')); }
                function ctEsc(s) {
                    return String(s == null ? '' : s)
                        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
                        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
                }

                /* ── URL ของ 1 หน้า พร้อมเงื่อนไขค้นหา/กรอง/เรียงปัจจุบัน ── */
                function ctListUrl(page) {
                    var url = CT_API_LIST + '?page=' + page + '&perPage=' + CT_PER_PAGE
                            + '&sortBy=' + encodeURIComponent(SORT_STATE);
                    if (SEARCH_Q) { url += '&searchText=' + encodeURIComponent(SEARCH_Q); }
                    if (STATUS_STATE) { url += '&status=' + encodeURIComponent(STATUS_STATE); }
                    if (FILTER.sourceIds.length) { url += '&marketingChannelIds=' + encodeURIComponent(FILTER.sourceIds.join(',')); }
                    if (FILTER.countryId) { url += '&currentCountryId=' + encodeURIComponent(FILTER.countryId); }
                    if (FILTER.provinceId) { url += '&currentCityId=' + encodeURIComponent(FILTER.provinceId); }
                    if (FILTER.districtId) { url += '&currentDistrictId=' + encodeURIComponent(FILTER.districtId); }
                    if (FILTER.salePersonId) { url += '&salePersonId=' + encodeURIComponent(FILTER.salePersonId); }
                    return url;
                }

                /* ── ข้อความผิดพลาดตาม HTTP status ──
                   status มาได้ 2 ทาง: เลข status ที่ servlet ตอบ (fetch ไม่ ok) หรือ errorStatus
                   ที่ ProspectListService แนบมาบอกว่า backend ตัวจริงตอบอะไร
                   ค่าที่ไม่ใช่ตัวเลข (network error / undefined) → ข้อความรวมแบบเดิม ไม่มีเลขต่อท้าย */
                function ctErrMsg(status) {
                    var code = (typeof status === 'number' && status > 0) ? status : 0;
                    var text = CT_MSG_ERROR;
                    if (code === 401 || code === 403) { text = CT_MSG_ERR_AUTH; }
                    else if (code === 404) { text = CT_MSG_ERR_MISSING; }
                    else if (code >= 500) { text = CT_MSG_ERR_SERVER; }
                    /* I18n คืนชื่อ key เองถ้าไม่เจอข้อความ — กันไม่ให้ผู้ใช้เห็น "label.xxx" */
                    if (!text || text.indexOf('label.') === 0) { text = CT_MSG_ERROR; }
                    return code ? (text + ' (HTTP ' + code + ')') : text;
                }

                /* ── แถวสถานะ (ว่าง / โหลดไม่สำเร็จ) ── */
                function ctStatusRowHtml(text) {
                    return '<tr class="ct-status-row"><td colspan="' + CT_COLSPAN
                         + '" style="text-align:center;color:#9CA3AF;padding:32px;">' + ctEsc(text) + '</td></tr>';
                }
                /* ── โครงแถวระหว่างรอข้อมูล (skeleton) ── */
                function ctSkeletonHtml(rows) {
                    var widths = ['18px','70%','60%','80%','50%','70%','90%','60%','60%','60%'];
                    var html = '';
                    for (var r = 0; r < rows; r++) {
                        html += '<tr class="ct-skel-row">';
                        for (var c = 0; c < CT_COLSPAN; c++) {
                            html += '<td><div class="ct-skel-line" style="width:' + widths[c] + ';"></div></td>';
                        }
                        html += '</tr>';
                    }
                    return html;
                }
                function ctRemoveSkeleton() {
                    document.querySelectorAll('#ctTableBody .ct-skel-row').forEach(function (r) { r.remove(); });
                }

                /* ★ ที่อยู่ต่างประเทศ → ขึ้นชื่อประเทศ, ในไทย (หรือไม่ระบุประเทศ) → ขึ้นจังหวัด+เขต/อำเภอ
                   ที่อยู่เต็มยังอยู่ครบใน title (ชี้เมาส์ดูได้) ไม่มีข้อมูลหายไปจากหน้าจอ */
                function ctPanelAddress(d) {
                    /* ที่อยู่ปัจจุบัน = ที่อยู่ + แขวง/ตำบล + อำเภอ/เขต + จังหวัด (+ ประเทศถ้าอยู่ต่างประเทศ) ต่อกันด้วยเว้นวรรค ไม่เอารหัสไปรษณีย์
                       ข้อความที่มากับแถวบางทีเป็นที่อยู่เต็มอยู่แล้ว (มีอำเภอ/จังหวัด/รหัสไปรษณีย์) บางทีเป็นแค่บรรทัดแรก → เติมเฉพาะส่วนที่ยังไม่มี */
                    var s = function (v) { var t = String(v == null ? '' : v).trim(); return /^[-–—]+$/.test(t) ? '' : t; };   /* "-" = ไม่มีค่า → ไม่เอามาต่อ */
                    var a = s(d.addr).replace(/\s+/g, ' ').replace(/\s+\d{4,6}(-\d{3,4})?$/, '');
                    var c = s(d.country);
                    var foreign = !!c && !/^(ไทย|thailand)$/i.test(c);
                    [s(d.subdistrict), s(d.district), s(d.province), foreign ? c : ''].forEach(function (part) {
                        if (part && a.toLowerCase().indexOf(part.toLowerCase()) < 0) { a = (a ? a + ' ' : '') + part; }
                    });
                    return a;
                }
                function ctAddrDisplay(country, province, district, fullAddr) {
                    var c = String(country || '').trim();
                    var isForeign = !!c && !/^(ไทย|thailand)$/i.test(c);
                    var short = isForeign ? c
                        : [province, district].filter(function (s) { return s && String(s).trim(); }).join(', ');
                    return { text: short || '-', title: fullAddr || short || '-' };
                }

                /* ★ 15/09/2026 คอลัมน์ "เบอร์โทร" = รหัสโทร + เลขจัดรูปแบบ เช่น "+66 88-854-5457" — concept เดียวกับหน้า
                   โอกาสขาย/lead_detail (ไฟล์กลาง resources/js/phone_format.js — ห้าม copy logic มาเขียนซ้ำ)
                   r.phonecc = phoneCountryCode, r.countrycode = countryCode ของลูกค้า (ProspectListService.toRowJson)
                   ใช้ทั้งแถวในตาราง (r = JSON) และพาเนลรายละเอียดขวา (r = dataset ของแถว — key เดียวกัน)
                   master ประเทศยังไม่มาตอน render → เลขดิบไปก่อน แล้ว TsPhone.refresh() อัปเดตทุกแถวเองเมื่อโหลดเสร็จ */
                function ctPhoneHtml(r) {
                    if (/^\*+$/.test(String(r.phonecc == null ? '' : r.phonecc).trim())) { return '****'; }
                    if (!window.TsPhone) { return ctEsc(String(r.phone || '').trim() || '-'); }   /* ไฟล์กลางโหลดไม่ขึ้น → อย่าให้ทั้งตารางพัง */
                    return TsPhone.html(r.phone, r.phonecc, r.countrycode);
                }
                if (window.TsPhone) { TsPhone.load(); }

                /* ── สถานะ: จุดสี + ข้อความ (สีตามชนิดของสถานะ; ไม่รู้จัก = เทา) ── */
                function ctStatusKind(s) {
                    var v = String(s || '').toLowerCase();
                    if (/ลบ|delet|trash/.test(v)) { return 'deleted'; }
                    if (/ระงับ|suspend|inactive/.test(v)) { return 'suspended'; }
                    if (/ร่าง|draft/.test(v)) { return 'draft'; }
                    if (/เปิด|active|ใช้งาน/.test(v)) { return 'active'; }
                    return 'none';
                }
                function ctStatusHtml(s) {
                    /* the list does not send a status yet: default to "เปิดใช้งาน" */
                    var txt = String(s || '').trim() || env.t(STATUS_STATE ? 'app.prospects.status' + STATUS_STATE.charAt(0).toUpperCase() + STATUS_STATE.slice(1) : 'app.prospects.statusActive');
                    return '<span class="ct-st ct-st-' + ctStatusKind(txt) + '"><i class="ct-st-dot"></i>' + ctEsc(txt) + '</span>';
                }

                /* ── 1 แถวของตาราง (โครงเดียวกับที่ server เคย render) ── */
                function ctRowHtml(r) {
                    var name   = ctEsc(r.name);
                    var avatar = r.avatar ? ctEsc(r.avatar) : CT_AVATAR_DEF;
                    var source = ctEsc(r.source);
                    var sourceCell = r.source
                        ? '<span class="ct-badge ct-source-badge" data-source="' + source + '" title="' + source + '">'
                          + '<span class="ct-badge-text">' + source + '</span></span>'
                        : '<span class="ct-badge ct-badge-other">-</span>';
                    var addrInfo = ctAddrDisplay(r.country, r.province, r.district, r.addr);

                    var attrs = ['id','code','phone','phonecc','countrycode','source','addr','province','district','country','agentcode',
                                 'agent','team','owner','ownerid','oppcount','subdistrict','recorder','avatar','gender','type','email','line','fb','x','ig','availtime','availchannel'];
                    var dataAttrs = ' data-name="' + name + '"';
                    attrs.forEach(function (k) { dataAttrs += ' data-' + k + '="' + ctEsc(r[k]) + '"'; });

                    /* ★ เมนู 3 จุด (แก้ไข/ดู) แทนไอคอนลูกตาเดิมที่กดแล้วเข้าหน้าดูตรง ๆ — เปิด/ปิดด้วย ctCtxToggle */
                    return '<tr' + dataAttrs + ' onclick="ctOpenPanel(this)">'
                        + '<td onclick="event.stopPropagation();"><div class="ct-ctx-wrap">'
                        +   ((STATUS_STATE === 'deleted' ? (env.can('Pipeline_Prospect_Trash') || env.can('Pipeline_Prospect_View')) : ROW_MENU_ROLES.some(function (role) { return env.can(role); })) ? '<i class="fas fa-ellipsis-v ct-menu-btn" onclick="window.ctCtxToggle(\'' + r.id + '\',event)"></i>'
                        +   '<div class="ct-ctx-menu" id="ctCtx-' + r.id + '">'
                        +     (STATUS_STATE !== 'deleted' && env.can('Pipeline_Prospect_Edit') ? '<div class="ct-ctx-item" onclick="ctNavigate(\'' + CT_EDIT_URL + encodeURIComponent(r.id) + '\')"><i class="far fa-pen-to-square"></i>' + ctEsc(CT_MSG_EDIT) + '</div>' : '')
                        +     (env.can('Pipeline_Prospect_View') ? '<div class="ct-ctx-item" onclick="ctNavigate(\'' + CT_VIEW_URL + encodeURIComponent(r.id) + (STATUS_STATE === 'deleted' ? '&trash=1' : '') + '\')"><i class="far fa-eye"></i>' + ctEsc(CT_MSG_VIEW) + '</div>' : '')
                        +     (STATUS_STATE !== 'deleted' && env.can('Pipeline_Prospect_Change_Assign') ? '<div class="ct-ctx-item" id="ctCtxWaitlist-' + r.id + '"><i class="fas fa-rotate-left"></i>' + ctEsc(env.t('app.prospects.waitlist')) + '</div>' : '')
                        +     (STATUS_STATE !== 'deleted' ? ctStatusItem(r) : '')
                        +     (STATUS_STATE !== 'deleted' && env.can('Pipeline_Prospect_Trash') ? '<div class="ct-ctx-item ct-ctx-trash" id="ctCtxTrash-' + r.id + '" onclick="ctDeleteProspect(\'' + r.id + '\')"><i class="far fa-trash-can"></i>' + ctEsc(env.t('label.cmd.delete_tip')) + '</div>' : '')
                        +     (STATUS_STATE === 'deleted' && env.can('Pipeline_Prospect_Trash') ? '<div class="ct-ctx-item" id="ctCtxRestore-' + r.id + '" onclick="ctRestoreProspect(\'' + r.id + '\')"><i class="fas fa-trash-can-arrow-up"></i>' + ctEsc(env.t('app.prospects.restore')) + '</div>' : '')
                        +   '</div>' : '')
                        + '</div></td>'
                        + '<td class="ct-date">' + ctEsc(r.date) + '</td>'
                        + '<td class="ct-status">' + ctStatusHtml(r.status) + '</td>'
                        /* รหัสลูกค้าไม่ได้มากับ list → ขึ้นแถบ skeleton ไว้ก่อน แล้ว ctEnrichRows เติมให้ทีหลัง
                           (ดีกว่าปล่อยช่องว่างเปล่า ผู้ใช้จะได้รู้ว่ากำลังโหลด ไม่ใช่ลูกค้ารายนี้ไม่มีรหัส) */
                        + '<td class="ct-code">'
                        +   (r.code ? ctCodeLink(r.id, r.code) : '<div class="ct-skel-line" style="width:70%;"></div>') + '</td>'
                        + '<td><div class="ct-name-wrap"><div class="ct-avatar">'
                        +   '<img src="' + avatar + '" alt="" onerror="this.onerror=null;this.src=\'' + CT_AVATAR_DEF + '\';"/>'
                        +   '</div><span class="ct-name" title="' + name + '">' + name + '</span></div></td>'
                        + '<td>' + sourceCell + '</td>'
                        + '<td><div class="ct-phone"><span class="ct-phone-ic"><img src="' + CT_PHONE_ICON + '" alt=""/></span>'
                        +   ctPhoneHtml(r) + '</div></td>'
                        + '<td class="ct-addr" title="' + ctEsc(addrInfo.title) + '">' + ctEsc(addrInfo.text) + '</td>'
                                                + '<td class="ct-sp">' + ctOwnerCell(r.owner) + '</td>'
                        + '</tr>';
                }

                /* ── เมนู 3 จุดต่อแถว — position:fixed วางที่ไอคอน หนีการ clip ของ .ct-table-wrap (overflow:auto)
                   pattern เดียวกับ scCtxToggle ของ schedule.xhtml ให้พฤติกรรมตรงกันทั้งระบบ */
                window.ctCtxToggle = function (id, e) {
                    e.stopPropagation();
                    document.querySelectorAll('.ct-ctx-menu').forEach(function (m) { m.classList.remove('show'); });
                    var menu = document.getElementById('ctCtx-' + id);
                    if (!menu) { return; }
                    var icon = e.currentTarget || e.target;
                    var r = icon.getBoundingClientRect();
                    menu.style.left = r.left + 'px';
                    menu.style.top = (r.bottom + 4) + 'px';
                    menu.classList.add('show');
                    var mr = menu.getBoundingClientRect();
                    if (mr.right > window.innerWidth - 8) { menu.style.left = (window.innerWidth - mr.width - 8) + 'px'; }
                    if (mr.bottom > window.innerHeight - 8) { menu.style.top = (r.top - mr.height - 4) + 'px'; }
                };
                listen(document, 'click', function () {
                    document.querySelectorAll('.ct-ctx-menu.show').forEach(function (m) { m.classList.remove('show'); });
                });

                /* ── ต่อแถวเข้าตาราง (ข้ามแถวที่เคยต่อไปแล้ว) ── */
                function ctAppendRows(items) {
                    var body = g('ctTableBody');
                    if (!body) { return 0; }
                    var html = '', added = 0, needDetail = [];
                    items.forEach(function (r) {
                        var key = String(r.id || '') + '|' + String(r.code || '') + '|' + String(r.name || '');
                        if (CT_SEEN[key]) { return; }
                        CT_SEEN[key] = 1;
                        html += ctRowHtml(r);
                        added++;
                        /* ไม่มีรหัสลูกค้ามากับ list = ยังขาดข้อมูลอีกชุด (เพศ/ประเภท/อีเมล/โซเชียล/ที่อยู่ละเอียด)
                           วันไหน backend ใส่ code มากับ list เอง ลิสต์นี้จะว่าง = ไม่ยิงเส้นเติมเลย */
                        if (r.id && !r.code) { needDetail.push(String(r.id)); }
                    });
                    if (html) {
                        /* ★ แก้กระตุกตอนเลื่อนโหลดหน้าถัดไป — เดิม applyAll(body) ไล่ set สีทุกแถวที่
                           เคยโหลดมาแล้วซ้ำทุกครั้ง (ยิ่งเลื่อนลึกยิ่งมีแถวสะสมเยอะ ยิ่งกระตุกหนักขึ้น)
                           ตอนนี้ทำเฉพาะแถวที่เพิ่งต่อเข้าไปใหม่เท่านั้น */
                        var beforeCount = body.children.length;
                        body.insertAdjacentHTML('beforeend', html);
                        Array.prototype.slice.call(body.children, beforeCount).forEach(function (row) {
                            ctSourceBadgeColors.applyAll(row);
                        });
                    }
                    ctEnrichRows(needDetail);
                    return added;
                }

                /* ── เติมข้อมูลที่ list ไม่ส่งมา ให้แถวที่เพิ่งวาด (ตามหลัง ไม่บล็อกตาราง) ──
                   ★ 19/08: เดิม server ยิง GET /prospects/{id} ทีละแถว "ก่อน" ส่งตารางกลับ (blocking)
                     ตารางจึงไม่ขึ้นเลยจนกว่าจะครบทั้งหน้า และถ้าเส้นไหนช้าก็ค้างยกหน้า
                     ตอนนี้ตารางขึ้นก่อน แล้วขอส่วนที่ขาด "ครั้งเดียวต่อ 1 หน้า" ผ่าน /board/prospect-enrich
                     (ฝั่ง service ยิงขนาน 12 เส้น + cache ไว้ 2 นาที เลื่อนกลับมาดูซ้ำจึงไม่ยิงใหม่)
                     backend ยังไม่มี endpoint รับหลาย id ทีเดียว — ถ้ามีเมื่อไรแก้แค่ service ตัวเดียว */
                var CT_ENRICH_KEYS = ['code', 'gender', 'type', 'email', 'line', 'fb', 'x', 'ig',
                                      'availtime', 'availchannel', 'addr', 'province', 'district', 'subdistrict', 'country',
                                      'recorder', 'agentcode', 'agent', 'team', 'source', 'phone', 'phonecc', 'owner', 'ownerid'];
                function ctRowById(id) { return document.querySelector('#ctTableBody tr[data-id="' + id + '"]'); }
                /* เอา skeleton ในช่องรหัสลูกค้าออก — ใช้ทั้งตอนสำเร็จและตอนล้มเหลว ไม่ให้ค้างหมุนตลอด */
                function ctCodeLink(id, code) {
                    var trashq = STATUS_STATE === 'deleted' ? '&trash=1' : '';
                    return '<a class="ct-code-link" href="javascript:void(0)" onclick="event.stopPropagation();ctNavigate(\'' + CT_VIEW_URL + encodeURIComponent(id) + trashq + '\')">' + ctEsc(code) + '</a>';
                }
                function ctSetCodeCell(row, code) {
                    var cell = row.querySelector('.ct-code');
                    if (cell) { if (code) { cell.innerHTML = ctCodeLink(row.getAttribute('data-id'), code); } else { cell.textContent = ''; } }
                }
                function ctEnrichRows(ids) {
                    if (!ids || !ids.length) { return; }
                    env.fetch(CT_API_ENRICH + '?ids=' + encodeURIComponent(ids.join(',')), { credentials: 'same-origin' })
                        .then(function (res) { return res.ok ? res.json() : Promise.reject(res.status); })
                        .then(function (resp) {
                            var map = (resp && resp.result) || {};
                            ids.forEach(function (id) {
                                var row = ctRowById(id);
                                if (!row) { return; }
                                var d = map[id];
                                if (d) {
                                    CT_ENRICH_KEYS.forEach(function (k) {
                                        if (d[k] != null && String(d[k]) !== '') { row.setAttribute('data-' + k, d[k]); }
                                    });
                                    /* ★ ห้ามเซ็ต textContent เป็น d.addr ตรงๆ (ของเดิมทำแบบนั้น) — ตอนนี้ช่อง
                                       "ที่อยู่" โชว์สรุปสั้น (ประเทศ/จังหวัด+เขต) ไม่ใช่ที่อยู่เต็ม ต้องคำนวณใหม่
                                       จาก data-* ที่เพิ่งอัปเดตด้านบน (ผสมของเดิม+ที่ enrich เติมมาแล้ว) เสมอ */
                                    var addrCell = row.querySelector('.ct-addr');
                                    if (addrCell) {
                                        var addrInfo = ctAddrDisplay(row.getAttribute('data-country'),
                                            row.getAttribute('data-province'), row.getAttribute('data-district'),
                                            row.getAttribute('data-addr'));
                                        addrCell.textContent = addrInfo.text;
                                        addrCell.title = addrInfo.title;
                                    }
                                    /* ★ 18/09: ทีมขาย/พนักงานขาย/ผู้บันทึก — เหมือน addr ด้านบน ตอนวาดแถวครั้งแรก
                                       (ctRowHtml) list ยังไม่มีค่าจึงขึ้น "-" ไปก่อน enrich ได้ค่ามาทีหลัง (จาก
                                       quick-view fallback) ต้องอัปเดต textContent ของเซลล์เองตรงนี้ด้วย ไม่งั้น
                                       data-* ถูกต้องแล้วแต่ตัวเลขที่เห็นในตารางยังเป็น "-" ค้างเหมือนเดิม */
                                                                                                                                                                                }
                                row.setAttribute('data-enriched', '1');
                                ctSetCodeCell(row, row.getAttribute('data-code'));
                                /* panel ขวาเปิดค้างอยู่ที่แถวนี้ → วาดใหม่ด้วยข้อมูลที่ครบแล้ว */
                                if (row.classList.contains('ct-row-active')) { openPanel(row); }
                            });
                        })
                        .catch(function (err) {
                            console.error('[contracts list] เติมรายละเอียดลูกค้าไม่สำเร็จ:', err);
                            ids.forEach(function (id) {
                                var row = ctRowById(id);
                                if (row) { ctSetCodeCell(row, row.getAttribute('data-code')); }
                            });
                        });
                }

                /* ── โหลดหน้าแรกใหม่ทั้งหมด (ใช้ตอนเปิดหน้า/ค้นหา/กรอง/เปลี่ยนการเรียง) ── */
                function ctReload() {
                    CT_PAGE = 0; CT_TOTAL_PAGES = -1; CT_DONE = false; CT_SEEN = {};
                    var body = g('ctTableBody');
                    if (body) { body.innerHTML = ctSkeletonHtml(Math.min(CT_PER_PAGE, 10)); }
                    ctFetchNextPage();
                }

                /* ── ขอหน้าถัดไปต่อท้าย ── */
                function ctFetchNextPage() {
                    if (CT_LOADING || CT_DONE) { return; }
                    CT_LOADING = true;
                    var page = CT_PAGE + 1;
                    var body = g('ctTableBody');
                    if (page > 1 && body) { body.insertAdjacentHTML('beforeend', ctSkeletonHtml(3)); }

                    env.fetch(ctListUrl(page), { credentials: 'same-origin' })
                        .then(function (res) { return res.ok ? res.json() : Promise.reject(res.status); })
                        .then(function (resp) {
                            ctRemoveSkeleton();
                            var result = (resp && resp.result) || {};
                            var items  = result.items || [];
                            var meta   = result.meta  || {};
                            /* backend เรียกไม่สำเร็จ (ไม่ใช่ "ไม่มีข้อมูล") → บอกให้ชัดว่าโหลดไม่ได้
                               errorStatus = status ที่ backend ตัวจริงตอบ (0/ไม่มี = ยิงไม่ถึง) */
                            if (result.error) {
                                CT_DONE = true;
                                console.error('[contracts list] backend ตอบไม่สำเร็จ — errorStatus =', result.errorStatus);
                                if (!ctRows().length && body) { body.innerHTML = ctStatusRowHtml(ctErrMsg(result.errorStatus)); }
                                return;
                            }
                            if (meta.totalPages != null) { CT_TOTAL_PAGES = meta.totalPages; }
                            ctShowCounts(meta);
                            CT_PAGE = page;
                            ctAppendRows(items);
                            /* ไม่มี meta → ใช้ "ได้ไม่ครบ perPage = หน้าสุดท้าย" แทน */
                            CT_DONE = (CT_TOTAL_PAGES >= 0)
                                    ? (page >= CT_TOTAL_PAGES)
                                    : (items.length < CT_PER_PAGE);
                            /* หน้าถัดมาว่างเปล่า = หมดจริง (กันไล่ขอหน้าเปล่าไปเรื่อย ๆ ถ้า meta ไม่ตรงข้อมูล) */
                            if (!items.length && page > 1) { CT_DONE = true; }
                            if (!ctRows().length) { body.innerHTML = ctStatusRowHtml(CT_MSG_EMPTY); CT_DONE = true; }
                        })
                        .catch(function (err) {
                            ctRemoveSkeleton();
                            console.error('[contracts list] โหลดหน้า ' + page + ' ไม่สำเร็จ:', err);
                            if (!ctRows().length && body) { body.innerHTML = ctStatusRowHtml(ctErrMsg(err)); }
                            CT_DONE = true;   /* กันยิงซ้ำรัว ๆ ตอน backend ล่ม — รีเฟรช/ค้นหาใหม่ถึงจะลองอีกครั้ง */
                        })
                        .then(function () { CT_LOADING = false; ctFillViewport(); });
                }

                /* ── ตัวจับ "เลื่อนถึงท้ายตาราง" ──
                   ใช้ 2 ทางคู่กันให้ชัวร์ทุกเบราว์เซอร์:
                     1) IntersectionObserver จับ #ctScrollSentinel (div ท้าย .ct-table-wrap)
                     2) scroll listener — เผื่อ IO ไม่ทำงาน/ไม่มี
                   ทั้งคู่เรียก ctFetchNextPage() ซึ่งกันยิงซ้ำด้วย CT_LOADING/CT_DONE อยู่แล้ว */
                function initScrollWatch() {
                    var wrap = document.querySelector('.ct-table-wrap');
                    var sentinel = g('ctScrollSentinel');
                    if (!wrap) { return; }
                    if (window.IntersectionObserver && sentinel) {
                        if (CT_OBS) { CT_OBS.disconnect(); }
                        CT_OBS = track(new IntersectionObserver(function (entries) {
                            if (entries[0].isIntersecting) { ctFetchNextPage(); }
                        }, { root: wrap, rootMargin: CT_NEAR_END_PX + 'px' }));
                        CT_OBS.observe(sentinel);
                    }
                    /* ★ throttle ด้วย requestAnimationFrame — เดิมอ่าน scrollTop/clientHeight/
                       scrollHeight (บังคับ layout) ทุก scroll event ที่ยิงถี่มากตอนเลื่อน ทำให้
                       กระตุก; passive:true บอก browser ล่วงหน้าว่าไม่มี preventDefault ให้ scroll
                       ลื่นขึ้น (ตัวจับหลักคือ IntersectionObserver ด้านบน อันนี้เป็นแค่ fallback) */
                    var ctScrollTicking = false;
                    wrap.addEventListener('scroll', function () {
                        if (ctScrollTicking) { return; }
                        ctScrollTicking = true;
                        requestAnimationFrame(function () {
                            if (destroyed) { return; }
                            ctScrollTicking = false;
                            if (wrap.scrollTop + wrap.clientHeight >= wrap.scrollHeight - CT_NEAR_END_PX) {
                                ctFetchNextPage();
                            }
                        });
                    }, { passive: true });
                }

                /* แถวที่โหลดมายังไม่สูงพอให้เลื่อน → ไม่มี scroll event ให้จับ ต้องโหลดต่อเองจนกว่าจะเลื่อนได้ */
                function ctFillViewport() {
                    var wrap = document.querySelector('.ct-table-wrap');
                    if (!wrap || CT_DONE || CT_LOADING) { return; }
                    if (wrap.scrollHeight <= wrap.clientHeight + CT_NEAR_END_PX) { ctFetchNextPage(); }
                }

                function init() {
                    initScrollWatch();
                    ctReload();
                }

                function ctShowCounts(meta) {
                    var counts = (meta && meta.counts) || {};
                    var tot = g('ctTotalCount');
                    var all = counts.all != null ? counts.all : (!STATUS_STATE && meta && meta.total >= 0 ? meta.total : null);
                    if (tot && all != null) { tot.textContent = ' (' + all + ')'; }
                    document.querySelectorAll('#ctStatusChips .ct-chip').forEach(function (c) {
                        var k = c.getAttribute('data-status') || 'all';
                        var n = counts[k] != null ? counts[k] : (k === (STATUS_STATE || 'all') && meta && meta.total >= 0 ? meta.total : null);
                        var el = c.querySelector('.ct-chip-n');
                        if (el && n != null) { el.textContent = ' (' + n + ')'; }
                    });
                }
                function initStatusChips() {
                    var box = g('ctStatusChips');
                    if (!box) { return; }
                    box.querySelectorAll('.ct-chip').forEach(function (c) {
                        c.addEventListener('click', function () {
                            STATUS_STATE = c.getAttribute('data-status') || '';
                            box.querySelectorAll('.ct-chip').forEach(function (o) { o.classList.toggle('active', o === c); });
                            ctReload();
                        });
                    });
                }

                function initSort() {
                    var btn = g('ctSortBtn'), menu = g('ctSortMenu'), label = g('ctSortLabel');
                    if (!btn || !menu) return;
                    btn.addEventListener('click', function (e) {
                        e.stopPropagation();
                        menu.style.display = (menu.style.display === 'none' || !menu.style.display) ? 'block' : 'none';
                    });
                    menu.querySelectorAll('.ct-sort-item').forEach(function (it) {
                        it.addEventListener('click', function () {
                            SORT_STATE = it.getAttribute('data-sort');
                            if (label) label.textContent = it.textContent;
                            menu.style.display = 'none';
                            ctReload();   /* เรียงที่ backend → ต้องเริ่มนับหน้าใหม่ */
                        });
                    });
                    listen(document, 'click', function () { menu.style.display = 'none'; });
                }

                /* ── SEARCH (แว่นขยาย → ขยายเป็น input + ปุ่มค้นหา + x) ── */
                /* ★ 18/09: รายการแนะนำใต้ช่องค้นหา ย้ายไปใช้ component กลาง odsProspectSuggest แล้ว
                   (open_down_select.js) — เดิมหน้านี้เขียน fetch/debounce/render เองทั้งหมด ตอนนี้ขยายไป
                   ใช้อีกหลายหน้า (การติดต่อ/ข้อมูลประกอบ/ใบรับเงิน) จึงย้ายมาไว้จุดเดียวตาม DRY */
                function initSearchSuggest() {
                    if (!window.odsProspectSuggest) return;
                    var input = g('ldSearchInput');
                    if (!input) return;
                    odsProspectSuggest(input, {
                        apiUrl: CT_API_LIST,
                        contextPath: env.ctx,
                        fetch: env.fetch,
                        defaultAvatar: CT_AVATAR_DEF,
                        onPick: function (item) {
                            input.value = item && item.value ? item.value : input.value;
                            SEARCH_Q = input.value.trim();
                            ctReload();
                        }
                    });
                }

                function initSearch() {
                    var wrap = g('ldSearch');
                    if (!wrap) return;
                    var input = g('ldSearchInput'), clr = g('ldSearchClear'), go = g('ldSearchGo');
                    var ic = wrap.querySelector('.ld-search-ic');

                    function openSearch() { wrap.classList.add('open'); if (input) input.focus(); }
                    /* ค้นหาที่ backend → ครอบคลุมข้อมูลย้อนหลังทั้งหมด ไม่ใช่แค่แถวที่โหลดมาแล้ว */
                    function doSearch() {
                        SEARCH_Q = input ? input.value.trim() : '';
                        ctReload();
                    }
                    function closeSearch() {
                        wrap.classList.remove('open');
                        if (input) input.value = '';
                        if (SEARCH_Q) { SEARCH_Q = ''; ctReload(); }
                    }

                    if (ic) ic.addEventListener('click', function (e) {
                        e.stopPropagation();
                        if (wrap.classList.contains('open')) { if (input) input.focus(); } else { openSearch(); }
                    });
                    if (go) go.addEventListener('click', function (e) { e.stopPropagation(); doSearch(); });
                    if (clr) clr.addEventListener('click', function (e) { e.stopPropagation(); closeSearch(); });
                    if (input) input.addEventListener('keydown', function (e) {
                        if (e.key === 'Enter') { e.preventDefault(); doSearch(); }
                        else if (e.key === 'Escape') { closeSearch(); }
                    });
                }

                /* ★ ตัวเลือกตัวกรองมาจาก master data ของ backend (มี id) ไม่ใช่ distinct จากแถวในตาราง
                   — เพราะตอนนี้ตารางมีแค่หน้าที่โหลดมาแล้ว และ backend กรองด้วย id */
                function ctFetchJson(url) {
                    return env.fetch(url, { credentials: 'same-origin' })
                        .then(function (res) { return res.ok ? res.json() : Promise.reject(res.status); })
                        .catch(function (err) { console.error('[contracts list] โหลด master ไม่สำเร็จ:', url, err); return null; });
                }
                function ctAsList(data) {
                    if (!data) { return []; }
                    if (Array.isArray(data)) { return data; }
                    return data.result || [];
                }
                function ctFillSelect(sel, items, labelFn) {
                    if (!sel) return;
                    var html = '<option value="">' + ctEsc(CT_MSG_ALL) + '</option>';
                    items.forEach(function (o) {
                        html += '<option value="' + ctEsc(o.id) + '">' + ctEsc(labelFn ? labelFn(o) : (o.name || o.id)) + '</option>';
                    });
                    sel.innerHTML = html;
                }
                function ctOwnerCell(owner) {
                    var name = String(owner || '').trim();
                    if (!name) { return '-'; }
                    return '<div class="ct-agent"><div class="ct-agent-av"><img src="' + CT_AVATAR_DEF + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div><span class="ct-agent-txt">' + ctEsc(name) + '</span></div>';
                }
                var CT_OWNER_LIST = null;
                var CT_API_ASSIGN = env.ctx + '/board/prospect-assign';
                var CT_API_OWNERS = env.ctx + '/board/prospect-options?sets=responsibles,waitlists';
                /* โลโก้ X (Font Awesome 6.1 ยังไม่มี — วาดเป็น SVG; ใช้ currentColor) */
                var CT_X_LOGO = '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>';
                function ctOwnerMode(editing) {
                    var card = g('ctOwnerCard');
                    if (!card) { return; }
                    card.classList.toggle('editing', !!editing);
                    g('ctChangeOwnerLbl').textContent = env.t(editing ? 'app.prospects.formSave' : 'app.prospects.formChangeOwner');
                    g('ctChangeOwnerIc').className = editing ? 'fas fa-floppy-disk' : 'fas fa-user-pen';
                }
                function ctFillOwnerSelect(ownerName, ownerId) {
                    var sel = g('ctDOwnerSelect');
                    if (!sel) { return; }
                    var name = String(ownerName || '').trim();
                    var id = String(ownerId || '');
                    var fill = function (list) {
                        var rows = list.map(function (o) { return { id: String(o.id == null ? '' : o.id), name: o.name || o.code || '' }; });
                        /* the person now responsible is always there: by id, else (a row without an id) by name */
                        var known = rows.some(function (r) { return id ? r.id === id : r.name === name; });
                        if (name && !known) { rows.unshift({ id: id || name, name: name }); }
                        var current = rows.filter(function (r) { return id ? r.id === id : r.name === name; })[0];
                        /* nobody is responsible yet (or the row says nothing): a first empty choice, so the field is not a blank that looks broken */
                        sel.innerHTML = (current ? '' : '<option value="">-</option>') + rows.map(function (r) { return '<option value="' + ctEsc(r.id) + '">' + ctEsc(r.name) + '</option>'; }).join('');
                        sel.value = current ? current.id : '';
                    };
                    fill(CT_OWNER_LIST || []);
                    if (CT_OWNER_LIST) { return; }
                    ctFetchJson(CT_API_OWNERS).then(function (data) {
                        /* { responsibles: [...], waitlists: [...] }: the queues first, then the people (value wl:<id>; a queue with no name shows its id) */
                        var people = (data && data.responsibles) || [];
                        var queues = ((data && data.waitlists) || []).map(function (w) { return { id: 'wl:' + w.id, name: w.name || w.id }; });
                        CT_OWNER_LIST = queues.concat(people);
                        fill(CT_OWNER_LIST);
                    });
                }
                /* POST /prospects/{id}/assignments (through the backend): hand the prospect to another person, or (a value wl:<id>) to a queue; the status of the service says why not (403 no right,
                   409 somebody changed it meanwhile, 422 the receiver has no right) */
                function ctAssignOwner(prospectId, responsibleId, expectedId) {
                    return env.fetch(CT_API_ASSIGN, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'same-origin',
                        body: JSON.stringify(String(responsibleId).indexOf('wl:') === 0
                            ? { prospectId: prospectId, destination: 'WAITLIST', waitlistId: String(responsibleId).slice(3), expectedResponsibleId: expectedId || null, reason: null }
                            : { prospectId: prospectId, destination: 'EMPLOYEE', responsibleEmployeeId: responsibleId, expectedResponsibleId: expectedId || null, reason: null })
                    }).then(function (res) {
                        return res.text().then(function (t) {
                            if (res.ok) { return { ok: true }; }
                            var j = null;
                            try { j = JSON.parse(t); } catch (e) { j = null; }
                            var why = j && j.error ? (j.error.description || j.error.message || '') : '';
                            var msg = ({ 403: 'ไม่มีสิทธิ์เปลี่ยนผู้รับผิดชอบ', 409: 'ผู้รับผิดชอบถูกเปลี่ยนไปแล้ว กรุณารีเฟรชแล้วลองใหม่', 422: 'ผู้รับต้องมีสิทธิ์ผู้รับผิดชอบ' })[res.status] || ('เกิดข้อผิดพลาด (' + res.status + ')');
                            return { ok: false, message: msg + (why ? '\n' + why : '') };
                        });
                    }).catch(function () { return { ok: false, message: 'เชื่อมต่อเซิร์ฟเวอร์ไม่ได้' }; });
                }
                function ctFilterHasEmpty() {
                    var one = function (id) { var el = g(id); return !el || el.options.length <= 1; };
                    var noChips = document.querySelectorAll('#ctFilterOverlay .ct-filter-tag:not(.ct-filter-tag-all)').length === 0;
                    return noChips || one('ctFilterCountry') || one('ctFilterProvince') || one('ctFilterAgent');
                }
                function ctToggleSourceTag(wrap, tag) {
                    var all = wrap.querySelector('.ct-filter-tag-all');
                    if (tag === all) {
                        wrap.querySelectorAll('.ct-filter-tag').forEach(function (t) { t.classList.toggle('selected', t === all); });
                        return;
                    }
                    tag.classList.toggle('selected');
                    if (all) { all.classList.remove('selected'); }
                    if (all && !wrap.querySelector('.ct-filter-tag.selected')) { all.classList.add('selected'); }
                }
                function ctBuildFilterOptions() {
                    var wrap = document.querySelector('#ctFilterOverlay .ct-filter-tags');
                    ctFetchJson(CT_API_MASTER).then(function (data) {
                        var sources = ctAsList(data);
                        if (wrap) {
                            wrap.innerHTML = '<span class="ct-filter-tag ct-filter-tag-all selected" data-val="">' + ctEsc(CT_MSG_ALL) + '</span>' + sources.map(function (s) {
                                return '<span class="ct-filter-tag" data-val="' + ctEsc(s.id) + '">' + ctEsc(s.name || s.code) + '</span>';
                            }).join('');
                            wrap.querySelectorAll('.ct-filter-tag').forEach(function (tag) {
                                tag.addEventListener('click', function () { ctToggleSourceTag(wrap, tag); });
                            });
                        }
                        /* ช่องค้นหาที่มา: แสดงเฉพาะเมื่อมีตัวเลือกมากกว่า 10 อัน */
                        var tagSearch = g('ctFilterTagSearch');
                        if (tagSearch && wrap) {
                            if (sources.length > 10) {
                                tagSearch.style.display = '';
                                tagSearch.value = '';
                                tagSearch.oninput = function () {
                                    var q = this.value.trim().toLowerCase();
                                    wrap.querySelectorAll('.ct-filter-tag:not(.ct-filter-tag-all)').forEach(function (t) {
                                        var v = (t.textContent || '').toLowerCase();
                                        t.style.display = (!q || v.indexOf(q) !== -1) ? '' : 'none';
                                    });
                                };
                            } else {
                                tagSearch.style.display = 'none';
                                tagSearch.value = '';
                                tagSearch.oninput = null;
                            }
                        }
                    });
                    ctFetchJson(CT_API_COUNTRY).then(function (data) {
                        /* Thai UI: nameTh (the master's Thai name); English UI: name */
                        var th = env.t('label.cmd.country') === 'ประเทศ';
                        ctFillSelect(g('ctFilterCountry'), ctAsList(data), function (o) { return (th && o.nameTh) || o.name || o.code || ''; });
                    });
                    ctFetchJson(CT_API_PROV).then(function (data) {
                        ctFillSelect(g('ctFilterProvince'), ctAsList(data));
                    });
                    ctFetchJson(CT_API_AGENT_FILTER).then(function (data) {
                        /* ★ 28/09: พนักงานขาย โชว์แค่ชื่อ ไม่โชว์รหัส — value = salePerson.id */
                        ctFillSelect(g('ctFilterAgent'), ctAsList(data), function (o) {
                            return o.name || o.code || '';
                        });
                    });
                    ctFillSelect(g('ctFilterDistrict'), []);   /* อำเภอขึ้นกับจังหวัดที่เลือก */
                }
                /* จังหวัด → อำเภอ (cascade เหมือนหน้า board/กิจกรรม) */
                function ctLoadFilterDistricts(provinceId) {
                    var sel = g('ctFilterDistrict');
                    ctFillSelect(sel, []);
                    if (sel) { sel.disabled = true; }
                    if (!provinceId) { return; }
                    ctFetchJson(CT_API_DIST + encodeURIComponent(provinceId)).then(function (data) {
                        var current = g('ctFilterProvince');
                        if (current && current.value !== provinceId) { return; }
                        var districts = ctAsList(data);
                        ctFillSelect(sel, districts);
                        if (sel) { sel.disabled = districts.length === 0; }
                    });
                }

                /* ★ 27/08: รีเซ็ต select กลับไปตัวเลือกแรก ("ทั้งหมด") ให้ "ป้ายที่ผู้ใช้เห็น" เปลี่ยนตามด้วย
                   native select ทุกตัวในระบบถูกครอบด้วย ODS (open_down_select.js — template.xhtml โหลดให้
                   ทุกหน้า odsAutoEnhance() ครอบ <select> อัตโนมัติ) ตัว select จริงถูกซ่อน แล้วโชว์เป็นปุ่ม
                   .ods-btn แทน ซึ่ง sync ป้ายจาก 2 ทางเท่านั้น: childList mutation (option ถูกแทนที่ทั้งชุด)
                   กับ event 'change' ของ select — การ set selectedIndex ด้วย JS "ไม่ยิง change เอง"
                   ⇒ ค่าใน select ถูกล้างจริง (FILTER ว่าง ตารางโหลดใหม่ถูกต้อง) แต่ปุ่มยังโชว์ตัวเลือกเดิม
                   = อาการ "กดล้างค่าแล้วช่องพนักงานขายไม่ยอมล้าง" ที่ QA แจ้ง
                   (อำเภอไม่โดนอาการนี้เพราะ ctFillSelect ด้านล่างแทนที่ option ทั้งชุด = เข้าเงื่อนไข childList พอดี
                    ส่วนจังหวัด+พนักงานขายโดนทั้งคู่ — ของเดิม set selectedIndex เฉย ๆ)
                   แพทเทิร์นเดียวกับ setSelect() ใน js/lead/lead_create_dropdowns.js ที่เจอปัญหานี้มาก่อนแล้ว */
                function ctResetSelect(id) {
                    var el = g(id);
                    if (!el) { return; }
                    el.selectedIndex = 0;
                    el.dispatchEvent(new Event('change', { bubbles: true }));
                }

                function initFilter() {
                    var overlay  = g('ctFilterOverlay');
                    var openBtn  = g('ctFilterBtn');
                    var clearBtn = g('ctFilterClear');
                    var applyBtn = g('ctFilterApply');
                    var province = g('ctFilterProvince');

                    tmo(function () { if (!CT_FILTER_OPTS_LOADED) { CT_FILTER_OPTS_LOADED = true; ctBuildFilterOptions(); } }, 0);
                    if (openBtn) openBtn.addEventListener('click', function () {
                        if (!CT_FILTER_OPTS_LOADED) { CT_FILTER_OPTS_LOADED = true; ctBuildFilterOptions(); }
                        else if (ctFilterHasEmpty()) { ctBuildFilterOptions(); }
                        overlay.classList.add('show');
                    });
                    if (overlay) overlay.addEventListener('click', function (e) {
                        if (e.target === overlay) overlay.classList.remove('show');
                    });
                    if (province) province.addEventListener('change', function () {
                        ctLoadFilterDistricts(province.value);
                    });

                    if (clearBtn) clearBtn.addEventListener('click', function () {
                        document.querySelectorAll('#ctFilterOverlay .ct-filter-tag').forEach(function (t) {
                            t.classList.toggle('selected', t.classList.contains('ct-filter-tag-all')); t.style.display = '';
                        });
                        var tagSearch = g('ctFilterTagSearch');
                        if (tagSearch) tagSearch.value = '';
                        ['ctFilterCountry','ctFilterProvince','ctFilterDistrict','ctFilterAgent'].forEach(ctResetSelect);
                        ctFillSelect(g('ctFilterDistrict'), []);
                        FILTER = { sourceIds: [], countryId: '', provinceId: '', districtId: '', salePersonId: '' };
                        ctReload();
                    });

                    if (applyBtn) applyBtn.addEventListener('click', function () {
                        FILTER.sourceIds = [];
                        document.querySelectorAll('#ctFilterOverlay .ct-filter-tag.selected').forEach(function (t) {
                            if (t.getAttribute('data-val')) { FILTER.sourceIds.push(t.getAttribute('data-val')); }
                        });
                        FILTER.countryId     = g('ctFilterCountry') ? g('ctFilterCountry').value : '';
                        FILTER.provinceId    = province ? province.value : '';
                        FILTER.districtId    = g('ctFilterDistrict') ? g('ctFilterDistrict').value : '';
                        FILTER.salePersonId  = g('ctFilterAgent') ? g('ctFilterAgent').value : '';
                        ctReload();
                        overlay.classList.remove('show');
                    });
                }

                if (readyState === 'loading') {
                    onReady(function () { init(); initFilter(); initPanel(); initSort(); initStatusChips(); initSearch(); initSearchSuggest(); });
                } else { init(); initFilter(); initPanel(); initSort(); initStatusChips(); initSearch(); initSearchSuggest(); }
            })();

            /* ── Lead Confirm Popup ── */
            window.ctShowLeadConfirm = function(){
                var ov = document.getElementById('ctLeadConfirmOverlay');
                if(ov) ov.classList.add('show');
            };
            window.ctHideLeadConfirm = function(){
                var ov = document.getElementById('ctLeadConfirmOverlay');
                if(ov) ov.classList.remove('show');
            };
            window.ctConfirmLead = function(){
                window.ctHideLeadConfirm();
                /* เหมือนหน้า master_data: ยืนยัน → โชว์ success popup (รูปที่ 3) ก่อน ไม่ navigate ตรง ๆ */
                window.ctShowLeadSuccess();
            };
            /* ── Lead Success Popup (รูปที่ 3) ── */
            window.ctShowLeadSuccess = function(){
                var ov = document.getElementById('ctLeadSuccessOverlay');
                if(ov) ov.classList.add('show');
            };
            window.ctHideLeadSuccess = function(){
                var ov = document.getElementById('ctLeadSuccessOverlay');
                if(ov) ov.classList.remove('show');
            };
            window.ctGotoLeadPage = function(){
                /* ไปหน้าโอกาสขาย (lead) */
                env.navigate('lead.face?pid=1&page_id=3&act=3&action_type=list');
            };

            /* ── Modal สร้าง Lead (รูปที่ 3) — โหลด dropdown จริง + สร้าง lead จริงผ่าน /board/lead-create ── */
            /* ★ 14/09: logic ของ 4 dropdown (ผลิตภัณฑ์/กลุ่มขั้นตอน/ผู้รับผิดชอบ/พนักงานขาย) ย้ายไปรวมกับหน้า
               contracts_master_data.xhtml ที่ js/lead/lead_create_dropdowns.js แล้ว (เดิม copy-paste แยก
               กันคนละชุด clXxx/mdXxx จนเบี่ยงกันเอง — เช่น "พนักงานขาย" เคยกรองตามกลุ่มขั้นตอนเฉพาะฝั่งนี้) —
               เหลือแค่ init ตรงนี้ + alias ชื่อ clOnProductChange/clOnStepGroupChange เดิมไว้ให้ markup ข้างบนเรียก
               เหมือนเดิมไม่ต้องแก้ ส่วน clSubmit ยังอ่าน window.clSgRequired เหมือนเดิม (ดู onStepGroupRequiredChange) */
            var cl = env.leadCreateDropdowns({ fetch: env.fetch }).create({
                selectLabel: env.t("label.dashboard.select"),
                myEmployeeId: env.session.employeeId,
                onStepGroupRequiredChange: function(required){ window.clSgRequired = required; }
            });
            window.clOnProductChange = cl.onProductChange;
            window.clOnStepGroupChange = cl.onStepGroupChange;
            window.clOpenModal = function(){
                var pid = window.CT_CUR_PID;
                if(!pid || pid === '0'){ env.swal({ title: 'ข้อความแจ้งเตือน!', text: env.t("label.contracts.please_select_customer"), icon: 'warning', timer: 3000, buttons: false }); return; }
                cl.load();
                var m = document.getElementById('ctCreateLeadModal');
                if(m){
                    /* ย้ายไป <body> — หลุดจาก .layout-main ที่มี transform (containing block ของ position:fixed) */
                    if(m.parentNode !== document.body){ document.body.appendChild(m); }
                    m.classList.add('show');
                    if(window.requestAnimationFrame){ requestAnimationFrame(clCenter); } else { clCenter(); }
                }
            };
            /* จัดกล่อง modal ให้กลางจอเป๊ะ — measure-and-correct (ชนะ ancestor transform) */
            function clCenter(){
                var ov = document.getElementById('ctCreateLeadModal');
                if(!ov || !ov.classList.contains('show')){ return; }
                var box = ov.querySelector('.ct-cl-box');
                if(!box){ return; }
                box.style.transform = 'none';
                var r = box.getBoundingClientRect();
                if(!r.width){ return; }
                var dx = Math.round((window.innerWidth - r.width)/2 - r.left);
                var dy = Math.round((window.innerHeight - r.height)/2 - r.top);
                box.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
            }
            listen(window, 'resize', clCenter);
            window.clCloseModal = function(){ var m=document.getElementById('ctCreateLeadModal'); if(m) m.classList.remove('show'); };
            /* ★ 11/08: ข้อความ error จาก backend — เดิมโชว์แค่ res.message ("Validation error" ลอย ๆ)
               ไม่บอกว่า field ไหนพัง ทำให้ไล่สาเหตุไม่ได้ ต้องดึงรายละเอียดใน res.error มาด้วย */
            function clErrText(res){
                if(!res){ return ''; }
                var parts = [];
                if(res.message){ parts.push(res.message); }
                var e = res.error;
                if(e){
                    if(typeof e === 'string'){ parts.push(e); }
                    else {
                        if(e.message && e.message !== res.message){ parts.push(e.message); }
                        var det = e.details || e.fieldErrors || e.errors;
                        if(det){
                            try { parts.push(typeof det === 'string' ? det : JSON.stringify(det)); } catch(ex){}
                        }
                    }
                }
                return parts.length ? (': ' + parts.join(' — ')) : '';
            }
            /* กันสร้าง Lead ซ้ำจาก Prospect + ผลิตภัณฑ์เดิมใน browser session เดียวกัน
               ปุ่ม disabled กันได้เฉพาะตอน request ยังไม่จบ แต่เดิมพอ response สำเร็จแล้ว
               ผู้ใช้ปิด popup/refresh และกดซ้ำได้ทันที จึงต้องจำ operation ที่สำเร็จแล้วด้วย */
            var CL_LEAD_SCOPE = env.session.username + '|' + env.session.branchCode;
            var CL_CREATED_STORAGE_KEY = 'triplesale.createdLeadKeys.' + CL_LEAD_SCOPE;
            var CL_CREATED_TTL_MS = 15 * 60 * 1000;
            var CL_CREATED_LEADS = {};
            function clLoadCreatedLeads(){
                try { CL_CREATED_LEADS = JSON.parse(env.storage.getItem(CL_CREATED_STORAGE_KEY) || '{}') || {}; }
                catch(ex){ CL_CREATED_LEADS = {}; }
            }
            function clLeadKey(prospectId, movementTypeId){
                return String(prospectId || '') + ':' + String(movementTypeId || '');
            }
            function clWasLeadCreated(key){
                var createdAt = Number(CL_CREATED_LEADS[key] || 0);
                if(createdAt && Date.now() - createdAt < CL_CREATED_TTL_MS){ return true; }
                if(createdAt){ delete CL_CREATED_LEADS[key]; }
                return false;
            }
            function clRememberLeadCreated(key){
                CL_CREATED_LEADS[key] = Date.now();
                try { env.storage.setItem(CL_CREATED_STORAGE_KEY, JSON.stringify(CL_CREATED_LEADS)); }
                catch(ex){}
            }
            function clCreateSucceeded(res){
                if(!res){ return false; }
                var status = Number(res.status != null ? res.status : res.code);
                return status === 200 || status === 201;
            }
            clLoadCreatedLeads();
            window.clSubmit = function(){
                var pid = window.CT_CUR_PID;
                var mt = document.getElementById('clProduct').value;
                if(!pid || pid === '0'){ env.swal({ title: 'ข้อความแจ้งเตือน!', text: env.t("label.contracts.please_select_customer"), icon: 'warning', timer: 3000, buttons: false }); return; }
                if(!mt){ env.swal({ title: 'ข้อความแจ้งเตือน!', text: env.t("label.contracts.please_select_product"), icon: 'warning', timer: 3000, buttons: false }); return; }
                /* ★ 11/08: กลุ่มขั้นตอนบังคับเฉพาะตอนผลิตภัณฑ์นี้มีกลุ่มขั้นตอนให้เลือกจริง
                   ผลิตภัณฑ์ที่ไม่มี WorkFlow Step / ยังไม่มี group pipeline → ข้ามไป สร้าง Lead ได้เลย */
                var sg = (document.getElementById('clStepGroup')||{}).value || '';
                if(window.clSgRequired && !sg){ env.swal({ title: 'ข้อความแจ้งเตือน!', text: env.t("label.contracts.please_select_step_group"), icon: 'warning', timer: 3000, buttons: false }); return; }
                var leadKey = clLeadKey(pid, mt);
                if(clWasLeadCreated(leadKey)){
                    env.swal({ title: 'มี Opportunity นี้แล้ว', text: 'ลูกค้าและสายงานขายที่เลือกถูกสร้าง Opportunity สำเร็จแล้ว กรุณาตรวจสอบที่หน้าโอกาสขาย', icon: 'warning' })
                        .then(function(){ window.ctGotoLeadPage(); });
                    return;
                }
                var body = {
                    prospectId: pid,
                    movementTypeId: mt,
                    procedureGroupId: sg || 0,   /* ไม่มีกลุ่มขั้นตอน → 0 (LeadCreateServlet ตัดทิ้ง ไม่ส่งให้ backend) */
                    /* พนักงานขาย/ผู้รับผิดชอบ ไม่บังคับ — ไม่เลือกส่ง 0 (backend มอบหมายอัตโนมัติ) */
                    assignToId: (document.getElementById('clSales')||{}).value || 0,
                    employeeId: (document.getElementById('clOwner')||{}).value || 0
                };
                var btn = document.getElementById('clSubmitBtn');
                if(btn){ btn.disabled = true; btn.textContent = env.t("label.contracts.creating_btn"); }
                env.fetch(env.ctx + '/board/lead-create', {
                    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
                    body: JSON.stringify(body)
                }).then(function(r){ return r.json().catch(function(){ return {}; }); })
                  .then(function(res){
                      var ok = clCreateSucceeded(res);
                      if(ok){ clRememberLeadCreated(leadKey); }
                      if(ok && res.ownerAssigned === false){
                          /* Lead ถูกสร้างแล้ว: ต้องปิด modal และออกจาก flow นี้ กันผู้ใช้กดซ้ำจนได้ Lead ซ้ำ */
                          window.clCloseModal();
                          env.swal({ title: 'สร้าง Opportunity สำเร็จ แต่ผูกผู้รับผิดชอบไม่สำเร็จ', text: res.ownerAssignMessage || 'กรุณาเพิ่มผู้รับผิดชอบจากหน้า Opportunity', icon: 'warning' })
                              .then(function(){ window.ctGotoLeadPage(); });
                      }
                      else if(ok){ window.clCloseModal(); window.ctShowLeadSuccess(); }
                      else { env.swal({ title: 'บันทึกไม่สำเร็จ!', text: env.t("app.prospects.createOpportunityFailed") + clErrText(res), icon: 'error' }); }
                  })
                  .catch(function(){ env.swal({ title: 'บันทึกไม่สำเร็จ!', text: env.t("label.dashboard.backend_error"), icon: 'error' }); })
                  .then(function(){ if(btn){ btn.disabled=false; btn.textContent=env.t("app.prospects.createOpportunity"); } });
            };
            /* ปิด modal เมื่อคลิกพื้นหลัง */
            onReady(function(){
                var m = document.getElementById('ctCreateLeadModal');
                if(m) m.addEventListener('click', function(e){ if(e.target===m) window.clCloseModal(); });
            });
            /* close on overlay click */
            onReady(function(){
                var ov = document.getElementById('ctLeadConfirmOverlay');
                if(ov) ov.addEventListener('click', function(e){ if(e.target===ov) window.ctHideLeadConfirm(); });
                var ovs = document.getElementById('ctLeadSuccessOverlay');
                if(ovs) ovs.addEventListener('click', function(e){ if(e.target===ovs) window.ctHideLeadSuccess(); });
            });
            /* ================= อัปโหลดเอกสาร — เลือกไฟล์ หรือ ลากมาวาง =================
               ★ 26/08: ของเดิมทำได้ทีละ 1 ไฟล์ ต้องกดปุ่มเลือกเท่านั้น และระหว่างอัปโหลด
                 "ไม่มีอะไรขยับบนจอเลย" (ปุ่มเหมือนเดิม ไม่มีสปินเนอร์ รายการเพิ่งขึ้นตอนจบ)
                 ไฟล์ใหญ่ = จอนิ่งยาว ผู้ใช้ไม่รู้ว่าระบบทำงานอยู่หรือค้าง
                 ตอนนี้: ลากไฟล์มาวางได้ (หลายไฟล์พร้อมกัน) + ปุ่ม busy + แถบ "กำลังอัปโหลด i/n — ชื่อไฟล์"
               ★★ เปลี่ยนช่องทางส่งไฟล์จาก p:remoteCommand -> fetch ไป /board/prospect/attachments
                 (servlet ตัวเดียวกับที่ contracts_master_data.face กับ lead_detail.face ใช้อยู่แล้ว)
                 เหตุผล: remoteCommand ส่งแบบ form-urlencoded ติดเพดาน Tomcat maxPostSize 2MB
                 ไฟล์ base64 บวม ~1.37 เท่า + url-encode ต่อ ⇒ เกิน ~1.2MB Tomcat ตัดพารามิเตอร์ทิ้ง
                 bean ไม่เห็น docB64 → เงียบสนิท ไม่มีทั้งไฟล์และ error (ปัญหาเดิมที่หน้า
                 contracts_master_data แก้ไปตั้งแต่ 10/08) — ถ้าไม่แก้ ลากไฟล์เอกสารทั่วไป
                 (สแกน pdf มักเกิน 1.2MB) มาวางแล้วจะ "ดูเหมือนอัปสำเร็จแต่ไม่มีไฟล์ขึ้น"
                 หมายเหตุ: เมธอดฝั่ง Java ที่เคยรับ remoteCommand ตัวนี้ (ContractView) ถูกลบทิ้งแล้ว
                 ตอนนี้ทุกหน้าอัปโหลดผ่าน servlet /board/prospect/attachments ทางเดียว */
            /* ★ 26/08 เพดานขนาดไฟล์ — เดิมตั้งไว้ 20 MB ซึ่ง "เป็นไปไม่ได้" ตั้งแต่แรก
               backend ตั้ง Jackson StreamReadConstraints.getMaxStringLength() = 20,000,000 ตัวอักษร
               ต่อ 1 ค่า string ใน JSON และไฟล์ถูกส่งเป็น base64 ใน field fileContentBase64
               base64 ยาว = 4 * ceil(bytes/3) ⇒ ไฟล์ใหญ่สุดที่ backend รับได้ = 15,000,000 bytes ≈ 14.31 MiB
               (ยืนยันจากของจริง: ไฟล์ 14.34 MiB -> 20,051,112 ตัวอักษร -> backend ตอบ 400 "Malformed request body"
                error.message = "String value length (20051112) exceeds the maximum allowed (20000000...)")
               ⇒ เช็คด้วยความยาว base64 จริงไม่ใช่เดาเป็น MB จะได้ตรงกับสิ่งที่ backend วัด
               ถ้าวันหลัง backend ขยาย limit ให้แก้ CT_API_MAX_B64_CHARS ตัวเดียว */
            var CT_API_MAX_B64_CHARS = 20000000;
            var CT_MAX_FILE_BYTES = Math.floor(CT_API_MAX_B64_CHARS / 4) * 3;   /* = 15,000,000 bytes */
            var CT_MAX_FILE_MB = (CT_MAX_FILE_BYTES / 1024 / 1024).toFixed(1);  /* ไว้โชว์ในข้อความ = "14.3" */
            var CT_UP = { busy: false };
            var CT_UP_MSG = {
                upload:    env.t("label.contracts.upload_btn"),
                uploading: env.t("label.cmd.uploading"),
                done:      env.t("label.cmd.upload_done"),
                failed:    env.t("label.cmd.upload_fail_count"),
                fileUnit:  env.t("label.cmd.file_unit"),
                tooLarge:  env.t("label.cmd.file_too_large"),
                uploadFail:env.t("label.ld2.upload_failed"),
                readFail:  env.t("label.cmd.file_read_failed"),
                pickCust:  env.t("label.contracts.please_select_customer")
            };
            /* ★ 28/09/2026 ตรวจนามสกุลไฟล์ "ก่อน" ยิง API (ไฟล์กลาง resources/js/attach_file_types.js — ชุดเดียวกับ lead_detail) */
            var CT_ATTACH_MSG = {
                notAllowed:    env.t("label.rv.file_type_not_allowed"),
                allowed:       env.t("label.rv.file_type_allowed")
            };

            /* ปุ่มระหว่างทำงาน: ไอคอนเป็นสปินเนอร์ + ข้อความ "กำลังอัปโหลด" + กดไม่ได้ */
            function ctSetUploadBusy(busy){
                CT_UP.busy = busy;
                var btn = document.getElementById('ctUploadBtn');
                if(!btn) return;
                btn.disabled = busy;
                var ic = document.getElementById('ctUploadBtnIc');
                if(ic) ic.className = busy ? 'fas fa-spinner fa-spin' : 'fas fa-arrow-up-from-bracket';
                var tx = document.getElementById('ctUploadBtnTxt');
                if(tx) tx.textContent = busy ? CT_UP_MSG.uploading : CT_UP_MSG.upload;
            }
            function ctShowUploadProgress(text){
                var box = document.getElementById('ctDocProgress');
                var tx  = document.getElementById('ctDocProgressText');
                if(tx) tx.textContent = text;
                if(box) box.style.display = 'flex';
            }
            function ctHideUploadProgress(){
                var box = document.getElementById('ctDocProgress');
                if(box) box.style.display = 'none';
            }

            /* อัปโหลดทีละไฟล์ตามลำดับ (ไม่ยิงพร้อมกัน — backend เขียนไฟล์ทีละใบและเราต้องรายงานความคืบหน้าทีละไฟล์) */
            function ctUploadFiles(files){
                if(CT_UP.busy) return;
                var pid = window.CT_CUR_PID;
                if(!pid || pid === '0'){
                    env.swal({ title: 'ข้อความแจ้งเตือน!', text: CT_UP_MSG.pickCust, icon: 'warning', timer: 3000, buttons: false });
                    return;
                }
                var list = Array.prototype.slice.call(files);
                if(!list.length) return;
                /* ทั้งเลือกไฟล์และลากมาวางผ่านตรงนี้ — มีไฟล์ไหนนามสกุลไม่ตรง → alert แล้วไม่อัปทั้งชุด */
                if(!TsAttachTypes.check(list, document.getElementById('ctFileInput').getAttribute('accept'), CT_ATTACH_MSG)) return;
                var total = list.length, okCount = 0, failCount = 0, unverifiedCount = 0, errs = [];
                ctSetUploadBusy(true);
                (function next(i){
                    if(i >= total){
                        ctHideUploadProgress();
                        ctSetUploadBusy(false);
                        if(window.rc_ctLoadDocs){ rc_ctLoadDocs([{ name:'pid', value: pid }]); }  /* วาดรายการใหม่จาก server */
                        /* สรุปผลเสมอ 3 กรณี: สำเร็จล้วน / พังบางส่วน / พังหมด
                           ★ 26/08: แยกเคส "พังหมด" ออกมา — ของเดิมขึ้นหัวข้อ "อัปโหลดเสร็จ 0 ไฟล์"
                           ซึ่งอ่านแล้วสับสน (บอกว่าเสร็จแต่ไม่มีไฟล์ไหนขึ้นจริง)
                           ที่มี fail ต้องกดรับทราบเอง (ไม่ตั้ง timer) จะได้อ่านเหตุผลทัน */
                        if(failCount === 0 && unverifiedCount === 0){
                            env.swal({ title: CT_UP_MSG.done + ' ' + okCount + ' ' + CT_UP_MSG.fileUnit, icon: 'success', timer: 2000, buttons: false });
                        } else if(failCount === 0){
                            /* servlet ตอบสำเร็จแต่ตรวจไฟล์จริงบน O2O ไม่พบบางไฟล์ — เตือนแทนขึ้น success เฉย ๆ */
                            env.swal({ title: CT_UP_MSG.done + ' ' + okCount + ' ' + CT_UP_MSG.fileUnit, text: errs.join('\n'), icon: 'warning' });
                        } else if(okCount === 0){
                            env.swal({ title: CT_UP_MSG.uploadFail, text: errs.join('\n'), icon: 'error' });
                        } else {
                            env.swal({ title: CT_UP_MSG.done + ' ' + okCount + ' ' + CT_UP_MSG.fileUnit
                                          + ' · ' + CT_UP_MSG.failed + ' ' + failCount + ' ' + CT_UP_MSG.fileUnit,
                                   text: errs.join('\n'), icon: 'warning' });
                        }
                        return;
                    }
                    var f = list[i];
                    ctShowUploadProgress(CT_UP_MSG.uploading + ' ' + (i + 1) + '/' + total + ' — ' + f.name);
                    if(f.size > CT_MAX_FILE_BYTES){
                        failCount++; errs.push(f.name + ' — ' + CT_UP_MSG.tooLarge + ' ' + CT_MAX_FILE_MB + ' MB');
                        next(i + 1);
                        return;
                    }
                    var reader = new FileReader();
                    reader.onload = function(e){
                        env.fetch(env.ctx + '/board/prospect/attachments', {
                            method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
                            body: JSON.stringify({ prospectId: pid, fileContentBase64: e.target.result,
                                                   fileName: f.name, description: f.name })
                        }).then(function(r){ return r.json().catch(function(){ return {}; }); })
                          .then(function(res){
                              if(res && (res.status === 200 || res.status === 201)){
                                  okCount++;
                                  if(res.verified === false){
                                      unverifiedCount++;
                                      errs.push(f.name + ' — ' + (res.message || CT_UP_MSG.uploadFail));
                                  }
                              }
                              else {
                                  /* หัวข้อ popup บอกว่า "อัปโหลดไม่สำเร็จ" อยู่แล้ว บรรทัดนี้จึงเอาเหตุผลจริงจาก backend มาโชว์
                                     (servlet ต่อ error.message ของ backend มาให้แล้ว เช่นเรื่องความยาว base64 เกินเพดาน) */
                                  failCount++;
                                  errs.push(f.name + ' — ' + (res && res.message ? res.message : CT_UP_MSG.uploadFail));
                              }
                          })
                          .catch(function(err){
                              console.error(err);
                              failCount++; errs.push(f.name + ' — ' + CT_UP_MSG.uploadFail);
                          })
                          .then(function(){ next(i + 1); });
                    };
                    reader.onerror = function(){
                        failCount++; errs.push(f.name + ' — ' + CT_UP_MSG.readFail);
                        next(i + 1);
                    };
                    reader.readAsDataURL(f);
                })(0);
            }

            /* ลากไฟล์มาวาง — รับทั้งแท็บ (#ctTabDocs) ไม่ใช่แค่กรอบพรีวิว ผู้ใช้ไม่ต้องเล็ง
               ใช้ตัวนับ dragenter/dragleave เพราะลากผ่านลูก ๆ ข้างในจะยิง dragleave ของตัวพ่อด้วย
               ถ้าไม่นับ เงาจะกะพริบตอนลากผ่านแถวเอกสาร */
            function ctBindDocDrop(){
                var zone = document.getElementById('ctTabDocs');
                if(!zone || zone.getAttribute('data-drop-bound')) return;
                zone.setAttribute('data-drop-bound', '1');
                var depth = 0;
                function hasFiles(e){
                    var dt = e.dataTransfer;
                    if(!dt) return false;
                    if(dt.types){
                        for(var i = 0; i < dt.types.length; i++){ if(dt.types[i] === 'Files') return true; }
                    }
                    return false;
                }
                zone.addEventListener('dragenter', function(e){
                    if(!hasFiles(e)) return;
                    e.preventDefault();
                    depth++;
                    zone.classList.add('ct-dragover');
                });
                zone.addEventListener('dragover', function(e){
                    if(!hasFiles(e)) return;
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'copy';
                });
                zone.addEventListener('dragleave', function(e){
                    if(!hasFiles(e)) return;
                    depth--;
                    if(depth <= 0){ depth = 0; zone.classList.remove('ct-dragover'); }
                });
                zone.addEventListener('drop', function(e){
                    if(!hasFiles(e)) return;
                    e.preventDefault();
                    depth = 0;
                    zone.classList.remove('ct-dragover');
                    if(e.dataTransfer.files && e.dataTransfer.files.length){ ctUploadFiles(e.dataTransfer.files); }
                });
                /* กันเบราว์เซอร์เปิดไฟล์แทนหน้าเว็บ เวลาผู้ใช้วางพลาดนอกกรอบ */
                ['dragover','drop'].forEach(function(evt){
                    listen(document, evt, function(e){
                        if(hasFiles(e) && !zone.contains(e.target)){ e.preventDefault(); }
                    });
                });
            }
            if(readyState === 'loading'){ onReady(ctBindDocDrop); }
            else { ctBindDocDrop(); }

            /* upload file -> show preview in gray box */
            window.ctPickFile = function(){
                if(CT_UP.busy) return;                    /* กันกดซ้ำระหว่างที่ยังอัปไม่เสร็จ = อัปซ้อนกัน */
                var inp = document.getElementById('ctFileInput');
                if(inp) inp.click();
            };
            /* shared preview renderer:
               - รูปภาพ/PDF -> แสดงเป็นรูปภาพ (img / ฝัง pdf)
               - word/excel -> แสดงเป็นโลโก้ตามชนิดไฟล์ (สีประจำ Office)
               - อื่น ๆ -> โลโก้ไฟล์ทั่วไป */
            window.ctRenderPreview = function(kind, src, name){
                var box = document.getElementById('ctDocPreview');
                if(!box) return;
                var safeName = (name || env.t("label.contracts.default_file_name")).replace(/</g,'&lt;');
                function logo(iconClass, color){
                    box.innerHTML = '<div class="ct-preview-file"><i class="' + iconClass + '" style="color:' + color + '"></i><span>' + safeName + '</span></div>';
                }
                if(kind === 'empty'){
                    box.innerHTML = '<span>' + env.t("label.contracts.no_preview") + '</span>';
                } else if(kind === 'image' && src){
                    box.innerHTML = '<img class="ct-preview-img" alt=""/>';
                    box.querySelector('img').src = src;
                } else if(kind === 'pdf' && src){
                    /* แสดง PDF เป็นรูปภาพ: ดึงผ่าน same-origin proxy (เลี่ยง CORS/X-Frame ของ file server)
                       -> blob -> ฝัง iframe. ถ้าดึงไม่ได้/ไม่ใช่ pdf -> โลโก้ PDF สีแดง */
                    var hash = '#toolbar=0&navpanes=0&scrollbar=0&view=Fit';
                    var embedPdf = function(u){
                        box.innerHTML = '<iframe class="ct-preview-pdf" title="PDF preview"></iframe>';
                        box.querySelector('iframe').src = u + hash;
                    };
                    if(src.indexOf('blob:') === 0){
                        embedPdf(src);  /* ไฟล์ที่เพิ่งอัปโหลด (local) ฝังตรงได้ */
                    } else {
                        env.fetch(env.ctx + '/docproxy?url=' + encodeURIComponent(src)).then(function(r){
                            var ct = r.headers.get('content-type') || '';
                            if(!r.ok || ct.indexOf('text/html') >= 0){ throw new Error('bad'); } /* html = โดน redirect login */
                            return r.blob();
                        }).then(function(b){
                            var pdf = (b.type === 'application/pdf') ? b : new Blob([b], {type:'application/pdf'});
                            embedPdf(URL.createObjectURL(pdf));
                        }).catch(function(){ logo('fas fa-file-pdf', '#CD1515'); });
                    }
                } else if(kind === 'word'){
                    logo('fas fa-file-word', '#2B579A');   /* โลโก้ Word สีน้ำเงิน */
                } else if(kind === 'excel'){
                    logo('fas fa-file-excel', '#217346');  /* โลโก้ Excel สีเขียว */
                } else {
                    logo('fas fa-file-lines', '#35236A');
                }
            };
            /* ดาวน์โหลดไฟล์เอกสาร (fetch เป็น blob เพื่อบังคับดาวน์โหลด + ตั้งชื่อไฟล์) */
            window.ctDownloadDoc = function(src, name){
                if(!src) return;
                var trigger = function(href, revoke){
                    var a = document.createElement('a');
                    a.href = href; a.download = name || 'download';
                    document.body.appendChild(a); a.click(); a.remove();
                    if(revoke) { downloadUrls.push(href); tmo(function(){ downloadUrls.splice(downloadUrls.indexOf(href), 1); URL.revokeObjectURL(href); }, 1000); }
                };
                if(src.indexOf('blob:') === 0){ trigger(src, false); return; }
                /* ไฟล์อยู่คนละ origin (file server) — ดึงตรงจากเบราว์เซอร์โดน CORS/ไฟร์วอลล์บาง environment = 404
                   ต้องผ่าน same-origin /docproxy เหมือนที่ preview PDF ทำอยู่แล้วด้านบน */
                var proxied = env.ctx + '/docproxy?url=' + encodeURIComponent(src);
                env.fetch(proxied).then(function(r){
                    if(!r.ok) { throw new Error(r.headers.get('X-DocProxy-Reason') || ('HTTP_' + r.status)); }
                    return r.blob();
                }).then(function(b){
                    trigger(URL.createObjectURL(b), true);
                }).catch(function(err){
                    /* err.message = รหัสสาเหตุจาก DocProxy (BLOCKED_HOST / UPSTREAM_404 / NETWORK ...) ให้ผู้ใช้แจ้งผู้ดูแลระบบได้ตรงจุด */
                    env.swal({ title: env.t("label.cmd.file_not_found_on_server"),
                           text: (err && err.message) ? ('[' + err.message + ']') : '', icon: 'error' });
                });
            };
            window.ctOnFilePicked = function(input){
                if(!input.files || !input.files.length) return;
                ctUploadFiles(input.files);          /* เส้นเดียวกับลากมาวาง — รองรับหลายไฟล์ */
                input.value = '';                    /* reset เพื่อให้เลือกไฟล์เดิมซ้ำได้ */
            };
  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = ["ctSourceBadgeColors","CT_CUR_PID","CT_DOCS_LOADED_PID","ctAfterDocsLoaded","ctDeleteDoc","ctDeleteProspect","ctRestoreProspect","ctChangeStatus","ctOpenPanel","ctCtxToggle","ctShowLeadConfirm","ctHideLeadConfirm","ctConfirmLead","ctShowLeadSuccess","ctHideLeadSuccess","ctGotoLeadPage","clSgRequired","clOnProductChange","clOnStepGroupChange","clOpenModal","clCloseModal","clSubmit","ctPickFile","ctRenderPreview","ctDownloadDoc","ctOnFilePicked","rc_ctLoadDocs","rc_ctDeleteDoc","ctNavigate"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    downloadUrls.splice(0).forEach(function (u) { try { URL.revokeObjectURL(u); } catch (e) {} });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
    /* the create-lead modal is moved to <body> when it is opened (out of any transformed ancestor) — take it away with the page */
    var modal = document.getElementById('ctCreateLeadModal');
    if (modal && modal.parentNode === document.body) { document.body.removeChild(modal); }
  };
}
